// 컨텍스트
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Lifecycle {
    Ephemeral(String),  // "2h", "30m" 등
    Persistent,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ContextBlock {
    pub lifecycle: Option<Lifecycle>,
    pub storage: Option<String>,
}

// ============================================================
// 표현식 (Expression)
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Expr {
    Int(i64),
    Float(f64),
    Str(String),
    Ident(String),
    BinOp {
        op: String,
        left: Box<Expr>,
        right: Box<Expr>,
    },
    Field {
        object: Box<Expr>,
        field: String,
    },
    Call {
        name: String,
        args: Vec<Expr>,
    },
}

