use world_engine::renderer::ViewRenderer;

const INVENTORY_FL: &str = r#"
intent InventoryWorld {
    schema Product {
        id: uuid @primary,
        name: string @required,
        qty: i64,
        price: f64,
    }

    action restock(product_id: uuid, amount: i64) {
        update Product set qty = qty + amount where id == product_id;
        return amount;
    }

    action add_product(name: string, qty: i64, price: f64) {
        return qty;
    }

    view ProductGrid {
        type: Grid,
        source: Product,
        interact: [restock, add_product],
    }

    view ProductList {
        type: List,
        source: Product,
        interact: [restock],
    }

    view ProductForm {
        type: Form,
        source: Product,
        interact: [],
    }
}
"#;

