use serde::{Deserialize, Serialize};

// ============================================================
// 타입 시스템
// ============================================================

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum FlType {
    I64,
    F64,
    String,
    Bool,
    Uuid,
    Custom(String),
}

impl std::fmt::Display for FlType {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            FlType::I64 => write!(f, "i64"),
            FlType::F64 => write!(f, "f64"),
            FlType::String => write!(f, "string"),
            FlType::Bool => write!(f, "bool"),
            FlType::Uuid => write!(f, "uuid"),
            FlType::Custom(s) => write!(f, "{}", s),
        }
    }
}

// ============================================================
// 어노테이션
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Annotation {
    Primary,
    Required,
    Default(String),  // 기본값 (raw 문자열)
    Check(String),    // 제약 표현식 (raw 문자열)
    Custom { name: String, arg: Option<String> },
}

// ============================================================
// 스키마
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SchemaField {
    pub name: String,
    pub field_type: FlType,
    pub annotations: Vec<Annotation>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Schema {
    pub name: String,
    pub fields: Vec<SchemaField>,
}

// ============================================================
// 뷰
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ViewType {
    Grid,
    List,
    Form,
    Custom(String),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct View {
    pub name: String,
    pub view_type: ViewType,
    pub source: String,
    pub interactions: Vec<String>,
}

// ============================================================
// 컨텍스트
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Lifecycle {
    Ephemeral(String),  // "2h", "30m" 등
    Persistent,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ContextBlock {
    pub lifecycle: Option<Lifecycle>,
    pub storage: Option<String>,
}

// ============================================================
// 표현식 (Expression)
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Expr {
    Int(i64),
    Float(f64),
    Str(String),
    Ident(String),
    BinOp {
        op: String,
        left: Box<Expr>,
        right: Box<Expr>,
    },
    Field {
        object: Box<Expr>,
        field: String,
    },
    Call {
        name: String,
        args: Vec<Expr>,
    },
}

// ============================================================
// 문장 (Statement)
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Assignment {
    pub field: String,
    pub value: Expr,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Stmt {
    Update {
        table: String,
        assignments: Vec<Assignment>,
        condition: Option<Expr>,
    },
    Return(Expr),
    Let {
        name: String,
        value: Expr,
    },
    Assign {
        name: String,
        value: Expr,
    },
    If {
        condition: Expr,
        then_body: Vec<Stmt>,
        else_body: Option<Vec<Stmt>>,
    },
}

// ============================================================
// 액션
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ActionParam {
    pub name: String,
    pub param_type: FlType,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Action {
    pub name: String,
    pub params: Vec<ActionParam>,
    pub body: Vec<Stmt>,
}

// ============================================================
// Intent 노드 (핵심)
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IntentNode {
    pub name: String,
    pub context: Option<ContextBlock>,
    pub schemas: Vec<Schema>,
    pub actions: Vec<Action>,
    pub views: Vec<View>,
}

// ============================================================
// FreeLang 기본 구조 (fn, struct)
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FnParam {
    pub name: String,
    pub param_type: FlType,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FnDef {
    pub name: String,
    pub params: Vec<FnParam>,
    pub return_type: Option<FlType>,
    pub body: Vec<Stmt>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StructField {
    pub name: String,
    pub field_type: FlType,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StructDef {
    pub name: String,
    pub fields: Vec<StructField>,
}

// ============================================================
// 최상위: Intent Graph
// ============================================================

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IntentGraph {
    pub intents: Vec<IntentNode>,
    pub functions: Vec<FnDef>,
    pub structs: Vec<StructDef>,
}

impl IntentGraph {
    pub fn new() -> Self {
        IntentGraph {
            intents: Vec::new(),
            functions: Vec::new(),
            structs: Vec::new(),
        }
    }
}

impl Default for IntentGraph {
    fn default() -> Self {
        Self::new()
    }
}

use std::collections::HashMap;
use crate::ast::*;

// ============================================================
// Value - KimDB 런타임 값 타입
// ============================================================

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Int(i64),
    Float(f64),
    Str(String),
    Bool(bool),
    Uuid(String),
    Null,
}

impl std::fmt::Display for Value {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Value::Int(n) => write!(f, "{}", n),
            Value::Float(n) => write!(f, "{:.6}", n),
            Value::Str(s) => write!(f, "{}", s),
            Value::Bool(b) => write!(f, "{}", b),
            Value::Uuid(u) => write!(f, "{}", u),
            Value::Null => write!(f, "NULL"),
        }
    }
}

pub type Row = HashMap<String, Value>;
