// ─── LifecycleManager ────────────────────────────────────────

const PERSISTENT_FL: &str = r#"
intent StableWorld {
    schema Config {
        id: uuid @primary,
        value: string,
    }
    action set_config(id: uuid, value: string) {
        return value;
    }
}
"#;

const EPHEMERAL_FL: &str = r#"
intent TempWorld {
    context {
        lifecycle: ephemeral(99999s),
        storage: KimDB.memory_buffer,
    }
    schema Session {
        id: uuid @primary,
        token: string,
    }
}
"#;

const SHORT_EPHEMERAL_FL: &str = r#"
intent QuickWorld {
    context {
        lifecycle: ephemeral(1s),
        storage: KimDB.memory_buffer,
    }
    schema Cache {
        id: uuid @primary,
        data: string,
    }
}
"#;

fn parse(src: &str) -> world_engine::IntentGraph {
    world_engine::parse(src).expect("파싱 실패")
}

#[test]
fn test_persistent_intent_is_always_alive() {
    let graph = parse(PERSISTENT_FL);
    let lc = LifecycleManager::from_graph(&graph);
    assert!(lc.is_alive("StableWorld"));
}

#[test]
fn test_persistent_no_remaining_secs() {
    let graph = parse(PERSISTENT_FL);
    let lc = LifecycleManager::from_graph(&graph);
    // persistent는 remaining_secs가 None
    assert_eq!(lc.remaining_secs("StableWorld"), None);
}

#[test]
fn test_ephemeral_intent_initially_alive() {
    let graph = parse(EPHEMERAL_FL);
    let lc = LifecycleManager::from_graph(&graph);
    assert!(lc.is_alive("TempWorld"));
}

#[test]
fn test_ephemeral_has_remaining_secs() {
    let graph = parse(EPHEMERAL_FL);
    let lc = LifecycleManager::from_graph(&graph);
    let rem = lc.remaining_secs("TempWorld");
    assert!(rem.is_some());
    assert!(rem.unwrap() > 0);
}

#[test]
fn test_unknown_intent_is_alive() {
    let graph = parse(PERSISTENT_FL);
    let lc = LifecycleManager::from_graph(&graph);
    // 등록되지 않은 intent는 기본 alive
    assert!(lc.is_alive("NoSuchIntent"));
}

#[test]
fn test_status_json_structure() {
    let graph = parse(EPHEMERAL_FL);
    let lc = LifecycleManager::from_graph(&graph);
    let status = lc.status_json();
    assert!(status["count"].as_u64().is_some());
    assert!(status["intents"].as_array().is_some());
}

#[test]
fn test_status_json_intent_fields() {
    let graph = parse(EPHEMERAL_FL);
    let lc = LifecycleManager::from_graph(&graph);
    let status = lc.status_json();
    let intents = status["intents"].as_array().unwrap();
    assert_eq!(intents.len(), 1);
    let entry = &intents[0];
    assert_eq!(entry["intent"].as_str().unwrap(), "TempWorld");
    assert_eq!(entry["type"].as_str().unwrap(), "ephemeral");
    assert!(entry["alive"].as_bool().unwrap());
    assert!(entry["ttl_secs"].as_u64().is_some());
    assert!(entry["remaining_secs"].as_u64().is_some());
}

#[test]
fn test_status_json_persistent_has_no_ttl() {
    let graph = parse(PERSISTENT_FL);
    let lc = LifecycleManager::from_graph(&graph);
    let status = lc.status_json();
    let intents = status["intents"].as_array().unwrap();
    let entry = &intents[0];
    assert_eq!(entry["type"].as_str().unwrap(), "persistent");
    assert!(entry.get("ttl_secs").is_none() || entry["ttl_secs"].is_null());
}

#[test]
fn test_table_names_in_lifecycle_entry() {
    let graph = parse(EPHEMERAL_FL);
    let lc = LifecycleManager::from_graph(&graph);
    let entry = &lc.entries[0];
    assert!(entry.table_names.contains(&"Session".to_string()));
}

// ─── clear_table (KimDB) ─────────────────────────────────────

#[test]
fn test_clear_table_removes_rows() {
    use std::collections::HashMap;
    use world_engine::synthesizer::kimdb::{KimDB, Value};

    let graph = parse(PERSISTENT_FL);
    let mut db = KimDB::new();
    for intent in &graph.intents {
        for schema in &intent.schemas {
            db.provision(schema);
        }
    }

    let mut row = HashMap::new();
    row.insert("value".to_string(), Value::Str("hello".to_string()));
    db.insert("Config", row).unwrap();
    assert_eq!(db.row_count("Config"), 1);

    db.clear_table("Config");
    assert_eq!(db.row_count("Config"), 0);
}

#[test]
fn test_clear_table_schema_preserved() {
    use std::collections::HashMap;
    use world_engine::synthesizer::kimdb::{KimDB, Value};

    let graph = parse(PERSISTENT_FL);
    let mut db = KimDB::new();
    for intent in &graph.intents {
        for schema in &intent.schemas {
            db.provision(schema);
        }
    }

    db.clear_table("Config");
    // 스키마는 남아있으므로 다시 insert 가능
    let mut row = HashMap::new();
    row.insert("value".to_string(), Value::Str("after clear".to_string()));
    let result = db.insert("Config", row);
    assert!(result.is_ok());
}

// ─── 짧은 TTL 만료 확인 ──────────────────────────────────────

#[test]
fn test_short_ephemeral_expires() {
    let graph = parse(SHORT_EPHEMERAL_FL);
    let lc = LifecycleManager::from_graph(&graph);

    // 처음엔 alive
    assert!(lc.is_alive("QuickWorld"));

    // 2초 대기 후 만료
    std::thread::sleep(std::time::Duration::from_millis(1100));
    assert!(!lc.is_alive("QuickWorld"));
}

#[test]
fn test_short_ephemeral_remaining_reaches_zero() {
    let graph = parse(SHORT_EPHEMERAL_FL);
    let lc = LifecycleManager::from_graph(&graph);

    std::thread::sleep(std::time::Duration::from_millis(1100));
    let rem = lc.remaining_secs("QuickWorld");
    assert_eq!(rem, Some(0));
}

