use world_engine::deficiency::{DeficiencyDetector, DeficiencyKind, Severity};

fn parse(src: &str) -> world_engine::IntentGraph {
    world_engine::parse(src).expect("파싱 실패")
}

// ─── 완전한 intent (결핍 없음) ───────────────────────────────

const PERFECT_FL: &str = r#"
intent ShopWorld {
    context {
        lifecycle: persistent,
        storage: KimDB.memory_buffer,
    }
    schema Product {
        id: uuid @primary,
        name: string @required,
        qty: i64 @default(0),
    }
    action restock(product_id: uuid, amount: i64) {
        update Product set qty = qty + amount where id == product_id;
        return amount;
    }
    view ProductGrid {
        type: Grid,
        source: Product,
        interact: [restock],
    }
}
"#;

#[test]
fn test_perfect_intent_has_no_deficiencies() {
    let graph = parse(PERFECT_FL);
    let deficiencies = DeficiencyDetector::analyze(&graph);
    assert!(deficiencies.is_empty(), "결핍 있음: {:?}", deficiencies.iter().map(|d| &d.kind).collect::<Vec<_>>());
}

#[test]
fn test_perfect_intent_report_is_healthy() {
    let graph = parse(PERFECT_FL);
    let report = DeficiencyDetector::report_json(&graph);
    assert!(report["healthy"].as_bool().unwrap());
    assert_eq!(report["total"].as_u64().unwrap(), 0);
}

// ─── @primary 없는 스키마 ─────────────────────────────────────

const NO_PRIMARY_FL: &str = r#"
intent TestWorld {
    context {
        lifecycle: persistent,
        storage: KimDB.memory_buffer,
    }
    schema Item {
        name: string @required,
        qty: i64,
    }
    action add(name: string) {
        return name;
    }
    view ItemGrid {
        type: Grid,
        source: Item,
        interact: [add],
    }
}
"#;

#[test]
fn test_detect_no_primary_key() {
    let graph = parse(NO_PRIMARY_FL);
    let deficiencies = DeficiencyDetector::analyze(&graph);
    assert!(deficiencies.iter().any(|d| d.kind == DeficiencyKind::NoPrimaryKey));
}

#[test]
fn test_no_primary_key_is_warning() {
    let graph = parse(NO_PRIMARY_FL);
    let d = DeficiencyDetector::analyze(&graph);
    let pk = d.iter().find(|d| d.kind == DeficiencyKind::NoPrimaryKey).unwrap();
    assert_eq!(pk.severity, Severity::Warning);
    assert_eq!(pk.target, "Item");
}

// ─── action에 return 없음 ─────────────────────────────────────

const NO_RETURN_FL: &str = r#"
intent TestWorld {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Product {
        id: uuid @primary,
        qty: i64,
    }
    action restock(product_id: uuid, amount: i64) {
        update Product set qty = qty + amount where id == product_id;
    }
    view ProductGrid {
        type: Grid,
        source: Product,
        interact: [restock],
    }
}
"#;

#[test]
fn test_detect_no_return_in_action() {
    let graph = parse(NO_RETURN_FL);
    let d = DeficiencyDetector::analyze(&graph);
    assert!(d.iter().any(|d| d.kind == DeficiencyKind::NoReturnInAction));
}

#[test]
fn test_no_return_is_info() {
    let graph = parse(NO_RETURN_FL);
    let d = DeficiencyDetector::analyze(&graph);
    let item = d.iter().find(|d| d.kind == DeficiencyKind::NoReturnInAction).unwrap();
    assert_eq!(item.severity, Severity::Info);
    assert_eq!(item.target, "restock");
}

// ─── view 없는 intent ─────────────────────────────────────────

const NO_VIEW_FL: &str = r#"
intent TestWorld {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Product {
        id: uuid @primary,
        qty: i64,
    }
    action add(qty: i64) {
        return qty;
    }
}
"#;

#[test]
fn test_detect_no_views() {
    let graph = parse(NO_VIEW_FL);
    let d = DeficiencyDetector::analyze(&graph);
    assert!(d.iter().any(|d| d.kind == DeficiencyKind::NoViews));
}

#[test]
fn test_no_views_is_warning() {
    let graph = parse(NO_VIEW_FL);
    let d = DeficiencyDetector::analyze(&graph);
    let item = d.iter().find(|d| d.kind == DeficiencyKind::NoViews).unwrap();
    assert_eq!(item.severity, Severity::Warning);
}

// ─── action 없는 intent ───────────────────────────────────────

const NO_ACTION_FL: &str = r#"
intent TestWorld {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Product {
        id: uuid @primary,
        qty: i64,
    }
    view ProductGrid {
        type: Grid,
        source: Product,
        interact: [],
    }
}
"#;

#[test]
fn test_detect_no_actions() {
    let graph = parse(NO_ACTION_FL);
    let d = DeficiencyDetector::analyze(&graph);
    assert!(d.iter().any(|d| d.kind == DeficiencyKind::NoActions));
}

// ─── context 없는 intent ──────────────────────────────────────

const NO_CONTEXT_FL: &str = r#"
intent TestWorld {
    schema Product {
        id: uuid @primary,
        name: string @required,
    }
    action add(name: string) {
        return name;
    }
    view ProductGrid {
        type: Grid,
        source: Product,
        interact: [add],
    }
}
"#;

#[test]
fn test_detect_no_context() {
    let graph = parse(NO_CONTEXT_FL);
    let d = DeficiencyDetector::analyze(&graph);
    assert!(d.iter().any(|d| d.kind == DeficiencyKind::NoContext));
}

#[test]
fn test_no_context_is_info() {
    let graph = parse(NO_CONTEXT_FL);
    let d = DeficiencyDetector::analyze(&graph);
    let item = d.iter().find(|d| d.kind == DeficiencyKind::NoContext).unwrap();
    assert_eq!(item.severity, Severity::Info);
}

// ─── 고아 스키마 ──────────────────────────────────────────────

const ORPHAN_SCHEMA_FL: &str = r#"
intent TestWorld {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Product {
        id: uuid @primary,
        name: string,
    }
    schema Archive {
        id: uuid @primary,
        reason: string,
    }
    action add(name: string) {
        return name;
    }
    view ProductGrid {
        type: Grid,
        source: Product,
        interact: [add],
    }
}
"#;

#[test]
fn test_detect_orphan_schema() {
    let graph = parse(ORPHAN_SCHEMA_FL);
    let d = DeficiencyDetector::analyze(&graph);
    assert!(d.iter().any(|d| d.kind == DeficiencyKind::OrphanSchema && d.target == "Archive"));
}

#[test]
fn test_orphan_schema_is_info() {
    let graph = parse(ORPHAN_SCHEMA_FL);
    let d = DeficiencyDetector::analyze(&graph);
    let item = d.iter().find(|d| d.kind == DeficiencyKind::OrphanSchema).unwrap();
    assert_eq!(item.severity, Severity::Info);
}

// ─── 고아 action ──────────────────────────────────────────────

const ORPHAN_ACTION_FL: &str = r#"
intent TestWorld {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Product {
        id: uuid @primary,
        qty: i64,
    }
    action restock(qty: i64) {
        return qty;
    }
    action delete_all() {
        return qty;
    }
    view ProductGrid {
        type: Grid,
        source: Product,
        interact: [restock],
    }
}
"#;

#[test]
fn test_detect_orphan_action() {
    let graph = parse(ORPHAN_ACTION_FL);
    let d = DeficiencyDetector::analyze(&graph);
    assert!(d.iter().any(|d| d.kind == DeficiencyKind::OrphanAction && d.target == "delete_all"));
}

// ─── interact 없는 view ───────────────────────────────────────

#[test]
fn test_detect_no_view_interactions() {
    let graph = parse(NO_ACTION_FL);
    let d = DeficiencyDetector::analyze(&graph);
    assert!(d.iter().any(|d| d.kind == DeficiencyKind::NoViewInteractions));
}

#[test]
fn test_no_view_interactions_is_info() {
