use std::path::{Path, PathBuf};
use std::sync::Mutex;
use std::time::SystemTime;
use crate::ast::IntentGraph;

// ============================================================
// HotReloader - .fl 파일 변경 감지 + 재파싱
// ============================================================

pub struct HotReloader {
    pub path: PathBuf,
    last_modified: Mutex<Option<SystemTime>>,
    last_reload: Mutex<Option<SystemTime>>,
    reload_count: Mutex<u64>,
    last_error: Mutex<Option<String>>,
}

impl HotReloader {
    pub fn new<P: AsRef<Path>>(path: P) -> Self {
        let path = path.as_ref().to_path_buf();
        // 초기 mtime 기록
        let initial_mtime = std::fs::metadata(&path)
            .and_then(|m| m.modified())
            .ok();

        HotReloader {
            path,
            last_modified: Mutex::new(initial_mtime),
            last_reload: Mutex::new(None),
            reload_count: Mutex::new(0),
            last_error: Mutex::new(None),
        }
    }

    // 파일 mtime을 확인해서 변경 여부 반환
    pub fn check_changed(&self) -> bool {
        let current = match std::fs::metadata(&self.path).and_then(|m| m.modified()) {
            Ok(t) => t,
            Err(_) => return false,
        };

        let mut last = self.last_modified.lock().unwrap();
        match *last {
            None => {
                *last = Some(current);
                false
            }
            Some(prev) => {
                if current != prev {
                    *last = Some(current);
                    true
                } else {
                    false
                }
            }
        }
    }

    // 파일을 읽어 IntentGraph 반환
    pub fn load_graph(&self) -> Result<IntentGraph, String> {
        let src = std::fs::read_to_string(&self.path)
            .map_err(|e| format!("파일 읽기 실패: {}", e))?;

        crate::parse(&src).map_err(|e| format!("파싱 오류: {}", e.message))
    }

    // 강제 리로드 (변경 여부 무관)
    pub fn force_reload(&self) -> Result<IntentGraph, String> {
        let result = self.load_graph();
        match &result {
            Ok(_) => {
                *self.last_reload.lock().unwrap() = Some(SystemTime::now());
                *self.reload_count.lock().unwrap() += 1;
                *self.last_error.lock().unwrap() = None;
            }
            Err(e) => {
                *self.last_error.lock().unwrap() = Some(e.clone());
            }
        }
        result
    }

    // 변경 확인 후 변경됐으면 리로드
    pub fn check_and_reload(&self) -> Option<Result<IntentGraph, String>> {
        if self.check_changed() {
            Some(self.force_reload())
        } else {
            None
        }
    }

    pub fn reload_count(&self) -> u64 {
        *self.reload_count.lock().unwrap()
    }

    pub fn last_error(&self) -> Option<String> {
        self.last_error.lock().unwrap().clone()
    }

    pub fn path_str(&self) -> String {
        self.path.to_string_lossy().to_string()
    }

    pub fn file_exists(&self) -> bool {
        self.path.exists()
    }

    // 상태 JSON
    pub fn status_json(&self) -> serde_json::Value {
        let last_reload = self.last_reload.lock().unwrap()
            .and_then(|t| t.duration_since(SystemTime::UNIX_EPOCH).ok())
            .map(|d| d.as_secs());

        let file_mtime = std::fs::metadata(&self.path)
            .and_then(|m| m.modified())
            .ok()
            .and_then(|t| t.duration_since(SystemTime::UNIX_EPOCH).ok())
            .map(|d| d.as_secs());

        let last_error = self.last_error.lock().unwrap().clone();

        let mut obj = serde_json::json!({
            "path": self.path_str(),
            "exists": self.file_exists(),
            "reload_count": self.reload_count(),
        });

        if let Some(ts) = last_reload {
            obj["last_reload_unix"] = serde_json::json!(ts);
        }
        if let Some(ts) = file_mtime {
            obj["file_mtime_unix"] = serde_json::json!(ts);
        }
        if let Some(err) = last_error {
            obj["last_error"] = serde_json::json!(err);
        }

        obj
    }
}

// ============================================================
// ReloadEvent - 리로드 이벤트 로그
// ============================================================

pub struct ReloadLog {
    events: Mutex<Vec<ReloadEvent>>,
}

struct ReloadEvent {
    ts: SystemTime,
    success: bool,
    message: String,
}

impl ReloadLog {
    pub fn new() -> Self {
        ReloadLog { events: Mutex::new(Vec::new()) }
    }

    pub fn record_ok(&self, intent_count: usize) {
        let mut log = self.events.lock().unwrap();
        log.push(ReloadEvent {
            ts: SystemTime::now(),
            success: true,
            message: format!("리로드 성공: {} intents", intent_count),
        });
        if log.len() > 50 {
            let excess = log.len() - 50;
            log.drain(0..excess);
        }
    }

    pub fn record_err(&self, err: &str) {
        let mut log = self.events.lock().unwrap();
        log.push(ReloadEvent {
            ts: SystemTime::now(),
            success: false,
            message: err.to_string(),
        });
        if log.len() > 50 {
            let excess = log.len() - 50;
            log.drain(0..excess);
        }
    }

    pub fn to_json(&self) -> serde_json::Value {
        let log = self.events.lock().unwrap();
        let events: Vec<serde_json::Value> = log.iter().rev().map(|e| {
            let ts = e.ts.duration_since(SystemTime::UNIX_EPOCH)
                .unwrap_or_default().as_secs();
            serde_json::json!({
                "ts_unix": ts,
                "success": e.success,
                "message": e.message,
            })
        }).collect();
        serde_json::json!({ "events": events, "count": events.len() })
    }
}

