    pub fn reload_count(&self) -> u64 {
        *self.reload_count.lock().unwrap()
    }

    pub fn last_error(&self) -> Option<String> {
        self.last_error.lock().unwrap().clone()
    }

    pub fn path_str(&self) -> String {
        self.path.to_string_lossy().to_string()
    }

    pub fn file_exists(&self) -> bool {
        self.path.exists()
    }

    // 상태 JSON
    pub fn status_json(&self) -> serde_json::Value {
        let last_reload = self.last_reload.lock().unwrap()
            .and_then(|t| t.duration_since(SystemTime::UNIX_EPOCH).ok())
            .map(|d| d.as_secs());

        let file_mtime = std::fs::metadata(&self.path)
            .and_then(|m| m.modified())
            .ok()
            .and_then(|t| t.duration_since(SystemTime::UNIX_EPOCH).ok())
            .map(|d| d.as_secs());

        let last_error = self.last_error.lock().unwrap().clone();

        let mut obj = serde_json::json!({
            "path": self.path_str(),
            "exists": self.file_exists(),
            "reload_count": self.reload_count(),
        });

        if let Some(ts) = last_reload {
            obj["last_reload_unix"] = serde_json::json!(ts);
        }
        if let Some(ts) = file_mtime {
            obj["file_mtime_unix"] = serde_json::json!(ts);
        }
        if let Some(err) = last_error {
            obj["last_error"] = serde_json::json!(err);
        }

        obj
    }
}

// ============================================================
// ReloadEvent - 리로드 이벤트 로그
// ============================================================

pub struct ReloadLog {
    events: Mutex<Vec<ReloadEvent>>,
}

struct ReloadEvent {
    ts: SystemTime,
    success: bool,
    message: String,
}

impl ReloadLog {
    pub fn new() -> Self {
        ReloadLog { events: Mutex::new(Vec::new()) }
    }

    pub fn record_ok(&self, intent_count: usize) {
        let mut log = self.events.lock().unwrap();
        log.push(ReloadEvent {
            ts: SystemTime::now(),
            success: true,
            message: format!("리로드 성공: {} intents", intent_count),
        });
        if log.len() > 50 {
            let excess = log.len() - 50;
            log.drain(0..excess);
        }
    }

    pub fn record_err(&self, err: &str) {
        let mut log = self.events.lock().unwrap();
        log.push(ReloadEvent {
            ts: SystemTime::now(),
            success: false,
            message: err.to_string(),
        });
        if log.len() > 50 {
            let excess = log.len() - 50;
            log.drain(0..excess);
        }
    }

    pub fn to_json(&self) -> serde_json::Value {
        let log = self.events.lock().unwrap();
        let events: Vec<serde_json::Value> = log.iter().rev().map(|e| {
            let ts = e.ts.duration_since(SystemTime::UNIX_EPOCH)
                .unwrap_or_default().as_secs();
            serde_json::json!({
                "ts_unix": ts,
                "success": e.success,
                "message": e.message,
            })
        }).collect();
        serde_json::json!({ "events": events, "count": events.len() })
    }
}

