use std::io::{BufRead, BufReader, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::{Arc, Mutex, RwLock};
use crate::synthesizer::kimdb::KimDB;
use crate::hotreload::HotReloader;
use crate::synthesizer::Synthesizer;
use super::router::Router;

// ============================================================
// 최소 HTTP 서버 (std only) + Hot-Reload 지원
// ============================================================

pub struct Server {
    pub port: u16,
    router: Arc<RwLock<Router>>,
    db: Arc<Mutex<KimDB>>,
    reloader: Option<Arc<HotReloader>>,
}

impl Server {
    pub fn new(router: Router, db: KimDB, port: u16) -> Self {
        Server {
            port,
            router: Arc::new(RwLock::new(router)),
            db: Arc::new(Mutex::new(db)),
            reloader: None,
        }
    }

    pub fn with_hot_reload(mut self, path: &str) -> Self {
        let reloader = Arc::new(HotReloader::new(path));
        // router에도 reloader 주입
        if let Ok(mut r) = self.router.write() {
            r.reloader = Some(Arc::clone(&reloader));
        }
        self.reloader = Some(reloader);
        self
    }

    pub fn start(&self) -> std::io::Result<()> {
        let listener = TcpListener::bind(format!("0.0.0.0:{}", self.port))?;
        println!("World Engine 서버 시작: http://0.0.0.0:{}", self.port);
        println!("라우트 목록:   http://0.0.0.0:{}/routes", self.port);
        println!("Lifecycle:     http://0.0.0.0:{}/lifecycle", self.port);
        println!("Deficiencies:  http://0.0.0.0:{}/deficiencies", self.port);
        println!("Reload status: http://0.0.0.0:{}/reload/status", self.port);

        // Lifecycle watcher
        {
            let db = Arc::clone(&self.db);
            let lifecycle = {
                let r = self.router.read().unwrap();
                Arc::clone(&r.lifecycle)
            };
            std::thread::spawn(move || {
                loop {
                    std::thread::sleep(std::time::Duration::from_secs(1));
                    if let (Ok(lc), Ok(mut db)) = (lifecycle.lock(), db.lock()) {
                        for entry in &lc.entries {
                            if entry.is_expired() {
                                for table in &entry.table_names {
                                    db.clear_table(table);
                                }
                            }
                        }
                    }
                }
            });
        }

        // Hot-reload watcher
        if let Some(reloader) = &self.reloader {
            let reloader = Arc::clone(reloader);
            let router_lock = Arc::clone(&self.router);
            let db_lock = Arc::clone(&self.db);
            println!("Hot-Reload ON: {}", reloader.path_str());

            std::thread::spawn(move || {
                loop {
                    std::thread::sleep(std::time::Duration::from_secs(1));
                    if let Some(result) = reloader.check_and_reload() {
                        match result {
                            Ok(new_graph) => {
                                // 새 스키마 provision (기존 데이터 유지)
                                if let Ok(mut db) = db_lock.lock() {
                                    let existing = db.table_names();
                                    for intent in &new_graph.intents {
                                        for schema in &intent.schemas {
                                            if !existing.contains(&schema.name) {
                                                db.provision(schema);
                                            }
                                        }
                                    }
                                }
                                // Router 교체
                                let new_router = Router::from_graph(new_graph)
                                    .with_reloader(Arc::clone(&reloader));
                                if let Ok(mut r) = router_lock.write() {
                                    *r = new_router;
                                    println!("[hot-reload] 라우트 갱신 완료 (reload #{})", reloader.reload_count());
                                }
                            }
                            Err(e) => {
                                eprintln!("[hot-reload] 오류: {}", e);
                            }
                        }
                    }
                }
            });
        }

        for stream in listener.incoming() {
            match stream {
                Ok(stream) => {
                    let router = Arc::clone(&self.router);
                    let db = Arc::clone(&self.db);
                    std::thread::spawn(move || {
                        handle_connection(stream, router, db);
                    });
                }
                Err(e) => eprintln!("연결 오류: {}", e),
            }
        }
        Ok(())
    }
}

fn handle_connection(
    mut stream: TcpStream,
    router: Arc<RwLock<Router>>,
    db: Arc<Mutex<KimDB>>,
) {
    let request = match parse_request(&stream) {
        Some(r) => r,
        None => {
            let _ = write_response(&mut stream, 400, r#"{"error":"bad request"}"#);
            return;
        }
    };

    let mut db = db.lock().unwrap();
    let router = router.read().unwrap();
    let (status, json) = router.handle(
        &mut db,
        &request.method,
        &request.path,
        &request.body,
    );

    // _html 마커: HTML 응답
    if let Some(html) = json.get("_html").and_then(|v| v.as_str()) {
        let _ = write_html_response(&mut stream, status, html);
    } else {
        let body = json.to_string();
        let _ = write_response(&mut stream, status, &body);
    }
}

// ─── HTTP 파싱 ──────────────────────────────────────────────

struct RawRequest {
    method: String,
    path: String,
    body: String,
}

fn parse_request(stream: &TcpStream) -> Option<RawRequest> {
    let mut reader = BufReader::new(stream);
    let mut lines = Vec::new();
    let mut content_length = 0usize;

    loop {
        let mut line = String::new();
        reader.read_line(&mut line).ok()?;
        let line = line.trim_end_matches("\r\n").trim_end_matches('\n').to_string();
        if line.is_empty() { break; }

        let lower = line.to_lowercase();
        if lower.starts_with("content-length:") {
            content_length = lower.split(':').nth(1)
                .and_then(|v| v.trim().parse().ok())
                .unwrap_or(0);
        }
        lines.push(line);
    }

    let first = lines.first()?;
    let parts: Vec<&str> = first.splitn(3, ' ').collect();
    if parts.len() < 2 { return None; }

