use world_engine::federation::{FederationMerger, ConflictKind, merge_files};

fn parse(src: &str) -> world_engine::IntentGraph {
    world_engine::parse(src).expect("파싱 실패")
}

fn write_fl(path: &str, content: &str) {
    std::fs::write(path, content).unwrap();
}

// ─── 기본 FL ─────────────────────────────────────────────────

const SHOP_FL: &str = r#"
intent ShopWorld {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Product {
        id: uuid @primary,
        name: string @required,
        price: f64,
    }
    action add_product(name: string, price: f64) {
        return name;
    }
    view ProductGrid {
        type: Grid,
        source: Product,
        interact: [add_product],
    }
}
"#;

const INVENTORY_FL: &str = r#"
intent InventoryWorld {
    context { lifecycle: ephemeral(1h), storage: KimDB.memory_buffer, }
    schema Stock {
        id: uuid @primary,
        item: string @required,
        qty: i64 @default(0),
    }
    action restock(item: string, qty: i64) {
        return qty;
    }
    view StockGrid {
        type: Grid,
        source: Stock,
        interact: [restock],
    }
}
"#;

const USER_FL: &str = r#"
intent UserWorld {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema User {
        id: uuid @primary,
        email: string @required,
    }
    action register(email: string) {
        return email;
    }
    view UserGrid {
        type: Grid,
        source: User,
        interact: [register],
    }
}
"#;

// 중복 intent (ShopWorld가 두 번)
const SHOP_DUPLICATE_FL: &str = r#"
intent ShopWorld {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Item {
        id: uuid @primary,
        code: string,
    }
    action add(code: string) {
        return code;
    }
    view ItemGrid {
        type: Grid,
        source: Item,
        interact: [add],
    }
}
"#;

// ─── add_graph / add_file ─────────────────────────────────────

#[test]
fn test_add_graph_increases_source_count() {
    let mut merger = FederationMerger::new();
    assert_eq!(merger.source_count(), 0);
    merger.add_graph("shop", parse(SHOP_FL));
    assert_eq!(merger.source_count(), 1);
    merger.add_graph("inventory", parse(INVENTORY_FL));
    assert_eq!(merger.source_count(), 2);
}

#[test]
fn test_add_file_ok_for_valid_path() {
    let path = "/tmp/we_fed_shop.fl";
    write_fl(path, SHOP_FL);
    let mut merger = FederationMerger::new();
    let result = merger.add_file(path);
    assert!(result.is_ok());
    assert_eq!(merger.source_count(), 1);
}

#[test]
fn test_add_file_err_for_missing_path() {
    let mut merger = FederationMerger::new();
    let result = merger.add_file("/tmp/we_no_such_federation_file.fl");
    assert!(result.is_err());
}

#[test]
fn test_add_file_err_for_invalid_fl() {
    let path = "/tmp/we_fed_invalid.fl";
    write_fl(path, "not valid FL @@@@");
    let mut merger = FederationMerger::new();
    let result = merger.add_file(path);
    assert!(result.is_err());
}

// ─── merge: 정상 합성 ─────────────────────────────────────────

#[test]
fn test_merge_two_intents() {
    let mut merger = FederationMerger::new();
    merger.add_graph("shop", parse(SHOP_FL));
    merger.add_graph("inventory", parse(INVENTORY_FL));
    let result = merger.merge();
    assert_eq!(result.merged.intents.len(), 2);
}

#[test]
fn test_merge_three_intents() {
    let mut merger = FederationMerger::new();
    merger.add_graph("shop", parse(SHOP_FL));
    merger.add_graph("inventory", parse(INVENTORY_FL));
    merger.add_graph("user", parse(USER_FL));
    let result = merger.merge();
    assert_eq!(result.merged.intents.len(), 3);
}

#[test]
fn test_merge_clean_when_no_conflicts() {
    let mut merger = FederationMerger::new();
    merger.add_graph("shop", parse(SHOP_FL));
    merger.add_graph("inventory", parse(INVENTORY_FL));
    let result = merger.merge();
    assert!(result.is_clean());
    assert!(result.conflicts.is_empty());
}

#[test]
fn test_merge_intent_names_preserved() {
    let mut merger = FederationMerger::new();
    merger.add_graph("shop", parse(SHOP_FL));
    merger.add_graph("inventory", parse(INVENTORY_FL));
    let result = merger.merge();
    let names: Vec<&str> = result.merged.intents.iter().map(|i| i.name.as_str()).collect();
    assert!(names.contains(&"ShopWorld"));
    assert!(names.contains(&"InventoryWorld"));
}

#[test]
fn test_merge_schemas_accessible() {
    let mut merger = FederationMerger::new();
    merger.add_graph("shop", parse(SHOP_FL));
    merger.add_graph("inventory", parse(INVENTORY_FL));
    let result = merger.merge();
    let shop = result.merged.intents.iter().find(|i| i.name == "ShopWorld").unwrap();
    assert!(shop.schemas.iter().any(|s| s.name == "Product"));
    let inv = result.merged.intents.iter().find(|i| i.name == "InventoryWorld").unwrap();
    assert!(inv.schemas.iter().any(|s| s.name == "Stock"));
}

#[test]
fn test_merge_empty_gives_empty_graph() {
    let merger = FederationMerger::new();
    let result = merger.merge();
    assert_eq!(result.merged.intents.len(), 0);
    assert!(result.is_clean());
}

// ─── merge: 충돌 감지 ─────────────────────────────────────────

#[test]
fn test_merge_detects_duplicate_intent() {
    let mut merger = FederationMerger::new();
    merger.add_graph("shop_a", parse(SHOP_FL));
    merger.add_graph("shop_b", parse(SHOP_DUPLICATE_FL));
    let result = merger.merge();
    assert!(!result.is_clean());
    assert!(result.conflicts.iter().any(|c| {
        matches!(&c.kind, ConflictKind::DuplicateIntent(n) if n == "ShopWorld")
    }));
}

#[test]
fn test_merge_duplicate_intent_keeps_first() {
    let mut merger = FederationMerger::new();
    merger.add_graph("shop_a", parse(SHOP_FL));
    merger.add_graph("shop_b", parse(SHOP_DUPLICATE_FL));
    let result = merger.merge();
    // ShopWorld는 한 번만 포함됨
    let count = result.merged.intents.iter().filter(|i| i.name == "ShopWorld").count();
    assert_eq!(count, 1);
    // 첫 번째 것 유지: Product 스키마 포함
    let shop = result.merged.intents.iter().find(|i| i.name == "ShopWorld").unwrap();
    assert!(shop.schemas.iter().any(|s| s.name == "Product"));
}

#[test]
fn test_merge_conflict_has_source_info() {
    let mut merger = FederationMerger::new();
    merger.add_graph("path/a.fl", parse(SHOP_FL));
    merger.add_graph("path/b.fl", parse(SHOP_DUPLICATE_FL));
    let result = merger.merge();
    let conflict = result.conflicts.iter()
        .find(|c| matches!(&c.kind, ConflictKind::DuplicateIntent(_)))
        .unwrap();
    assert_eq!(conflict.source_a, "path/a.fl");
    assert_eq!(conflict.source_b, "path/b.fl");
    assert!(!conflict.message.is_empty());
}

// ─── FederationResult::to_json ────────────────────────────────

#[test]
fn test_result_json_structure() {
    let mut merger = FederationMerger::new();
    merger.add_graph("shop", parse(SHOP_FL));
    merger.add_graph("inventory", parse(INVENTORY_FL));
    let result = merger.merge();
    let json = result.to_json();
    assert!(json["clean"].as_bool().unwrap());
    assert_eq!(json["conflict_count"].as_u64().unwrap(), 0);
    assert!(json["merged"]["intent_count"].as_u64().is_some());
    assert!(json["sources"].as_array().is_some());
    assert!(json["conflicts"].as_array().is_some());
}

#[test]
fn test_result_json_merged_counts() {
    let mut merger = FederationMerger::new();
    merger.add_graph("shop", parse(SHOP_FL));
    merger.add_graph("inventory", parse(INVENTORY_FL));
    let result = merger.merge();
    let json = result.to_json();
    assert_eq!(json["merged"]["intent_count"].as_u64().unwrap(), 2);
}

#[test]
fn test_result_json_sources_count() {
