const SHOP_FL: &str = r#"
intent ShopWorld {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Product {
        id: uuid @primary,
        name: string @required,
        price: f64,
    }
    action add_product(name: string, price: f64) {
        return name;
    }
    view ProductGrid {
        type: Grid,
        source: Product,
        interact: [add_product],
    }
}
"#;

const INVENTORY_FL: &str = r#"
intent InventoryWorld {
    context { lifecycle: ephemeral(1h), storage: KimDB.memory_buffer, }
    schema Stock {
        id: uuid @primary,
        item: string @required,
        qty: i64 @default(0),
    }
    action restock(item: string, qty: i64) {
        return qty;
    }
    view StockGrid {
        type: Grid,
        source: Stock,
        interact: [restock],
    }
}
"#;

const USER_FL: &str = r#"
intent UserWorld {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema User {
        id: uuid @primary,
        email: string @required,
    }
    action register(email: string) {
        return email;
    }
    view UserGrid {
        type: Grid,
        source: User,
        interact: [register],
    }
}
"#;

