// ============================================================

fn str_field(json: &serde_json::Value, key: &str) -> Result<String, String> {
    json[key].as_str()
        .map(|s| s.to_string())
        .ok_or_else(|| format!("'{}' 필드 없음 또는 문자열 아님", key))
}

fn parse_fl_type(s: &str) -> Result<FlType, String> {
    match s.trim().to_lowercase().as_str() {
        "i64" | "int" | "integer" => Ok(FlType::I64),
        "f64" | "float" | "double" => Ok(FlType::F64),
        "string" | "text" | "str" => Ok(FlType::String),
        "bool" | "boolean" => Ok(FlType::Bool),
        "uuid" => Ok(FlType::Uuid),
        other => Ok(FlType::Custom(other.to_string())),
    }
}

fn parse_view_type(s: &str) -> ViewType {
    match s.trim() {
        "Grid" | "grid" => ViewType::Grid,
        "List" | "list" => ViewType::List,
        "Form" | "form" => ViewType::Form,
        other => ViewType::Custom(other.to_string()),
    }
}

fn parse_lifecycle(s: &str) -> Result<Lifecycle, String> {
    let s = s.trim();
    if s == "persistent" {
        return Ok(Lifecycle::Persistent);
    }
    if let Some(inner) = s.strip_prefix("ephemeral(").and_then(|s| s.strip_suffix(')')) {
        // duration 유효성 확인
        crate::lifecycle::parse_duration(inner)
            .ok_or_else(|| format!("잘못된 duration: '{}'", inner))?;
        return Ok(Lifecycle::Ephemeral(inner.to_string()));
    }
    Err(format!("잘못된 lifecycle: '{}' (예: persistent, ephemeral(2h))", s))
}

