use world_engine::mutation::{MutationEngine, MutationOp};
use world_engine::ast::{FlType, ViewType, Lifecycle};

fn parse(src: &str) -> world_engine::IntentGraph {
    world_engine::parse(src).expect("파싱 실패")
}

const BASE_FL: &str = r#"
intent ShopWorld {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Product {
        id: uuid @primary,
        name: string @required,
        qty: i64 @default(0),
    }
    action restock(product_id: uuid, amount: i64) {
        update Product set qty = qty + amount where id == product_id;
        return amount;
    }
    view ProductGrid {
        type: Grid,
        source: Product,
        interact: [restock],
    }
}
"#;

// ─── AddField ──────────────────────────────────────────────

#[test]
fn test_add_field_success() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::AddField {
        intent: "ShopWorld".into(),
        schema: "Product".into(),
        field_name: "discount".into(),
        field_type: FlType::F64,
        required: false,
    };
    let (ok, msg) = eng.apply(&mut graph, op);
    assert!(ok, "실패: {}", msg);
    let schema = graph.intents[0].schemas.iter().find(|s| s.name == "Product").unwrap();
    assert!(schema.fields.iter().any(|f| f.name == "discount"));
}

#[test]
fn test_add_field_required() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::AddField {
        intent: "ShopWorld".into(),
        schema: "Product".into(),
        field_name: "sku".into(),
        field_type: FlType::String,
        required: true,
    };
    let (ok, _) = eng.apply(&mut graph, op);
    assert!(ok);
    let schema = graph.intents[0].schemas.iter().find(|s| s.name == "Product").unwrap();
    let f = schema.fields.iter().find(|f| f.name == "sku").unwrap();
    assert!(f.annotations.iter().any(|a| matches!(a, world_engine::ast::Annotation::Required)));
}

#[test]
fn test_add_field_duplicate_fails() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::AddField {
        intent: "ShopWorld".into(),
        schema: "Product".into(),
        field_name: "name".into(), // 이미 존재
        field_type: FlType::String,
        required: false,
    };
    let (ok, _) = eng.apply(&mut graph, op);
    assert!(!ok);
}

#[test]
fn test_add_field_unknown_intent_fails() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::AddField {
        intent: "NoSuchWorld".into(),
        schema: "Product".into(),
        field_name: "x".into(),
        field_type: FlType::I64,
        required: false,
    };
    let (ok, _) = eng.apply(&mut graph, op);
    assert!(!ok);
}

// ─── RemoveField ───────────────────────────────────────────

#[test]
fn test_remove_field_success() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::RemoveField {
        intent: "ShopWorld".into(),
        schema: "Product".into(),
        field_name: "qty".into(),
    };
    let (ok, _) = eng.apply(&mut graph, op);
    assert!(ok);
    let schema = graph.intents[0].schemas.iter().find(|s| s.name == "Product").unwrap();
    assert!(!schema.fields.iter().any(|f| f.name == "qty"));
}

#[test]
fn test_remove_field_nonexistent_fails() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::RemoveField {
        intent: "ShopWorld".into(),
        schema: "Product".into(),
        field_name: "nonexistent_xyz".into(),
    };
    let (ok, _) = eng.apply(&mut graph, op);
    assert!(!ok);
}

// ─── AddView ───────────────────────────────────────────────

#[test]
fn test_add_view_success() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::AddView {
        intent: "ShopWorld".into(),
        view_name: "ProductList".into(),
        view_type: ViewType::List,
        source: "Product".into(),
    };
    let (ok, _) = eng.apply(&mut graph, op);
    assert!(ok);
    let intent = &graph.intents[0];
    assert!(intent.views.iter().any(|v| v.name == "ProductList"));
}

#[test]
fn test_add_view_duplicate_fails() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::AddView {
        intent: "ShopWorld".into(),
        view_name: "ProductGrid".into(), // 이미 존재
        view_type: ViewType::Grid,
        source: "Product".into(),
    };
    let (ok, _) = eng.apply(&mut graph, op);
    assert!(!ok);
}

#[test]
fn test_add_view_unknown_source_fails() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::AddView {
        intent: "ShopWorld".into(),
        view_name: "GhostView".into(),
        view_type: ViewType::Grid,
        source: "NoSuchSchema".into(),
    };
    let (ok, _) = eng.apply(&mut graph, op);
    assert!(!ok);
}

// ─── RemoveView ────────────────────────────────────────────

#[test]
fn test_remove_view_success() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::RemoveView {
        intent: "ShopWorld".into(),
        view_name: "ProductGrid".into(),
    };
    let (ok, _) = eng.apply(&mut graph, op);
    assert!(ok);
    assert!(graph.intents[0].views.is_empty());
}

#[test]
fn test_remove_view_nonexistent_fails() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::RemoveView {
        intent: "ShopWorld".into(),
        view_name: "NoSuchView".into(),
    };
    let (ok, _) = eng.apply(&mut graph, op);
    assert!(!ok);
}

// ─── SetLifecycle ──────────────────────────────────────────

#[test]
fn test_set_lifecycle_to_ephemeral() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::SetLifecycle {
        intent: "ShopWorld".into(),
        lifecycle: Lifecycle::Ephemeral("30m".into()),
    };
    let (ok, _) = eng.apply(&mut graph, op);
    assert!(ok);
    let lc = &graph.intents[0].context.as_ref().unwrap().lifecycle;
    assert!(matches!(lc, Some(Lifecycle::Ephemeral(s)) if s == "30m"));
}

#[test]
fn test_set_lifecycle_to_persistent() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::SetLifecycle {
        intent: "ShopWorld".into(),
        lifecycle: Lifecycle::Persistent,
    };
    let (ok, _) = eng.apply(&mut graph, op);
    assert!(ok);
    let lc = &graph.intents[0].context.as_ref().unwrap().lifecycle;
    assert!(matches!(lc, Some(Lifecycle::Persistent)));
}

// ─── Mutation 이력 ────────────────────────────────────────

