use world_engine::mutation::{MutationEngine, MutationOp};
use world_engine::ast::{FlType, ViewType, Lifecycle};

fn parse(src: &str) -> world_engine::IntentGraph {
    world_engine::parse(src).expect("파싱 실패")
}

const BASE_FL: &str = r#"
intent ShopWorld {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Product {
        id: uuid @primary,
        name: string @required,
        qty: i64 @default(0),
    }
    action restock(product_id: uuid, amount: i64) {
        update Product set qty = qty + amount where id == product_id;
        return amount;
    }
    view ProductGrid {
        type: Grid,
        source: Product,
        interact: [restock],
    }
}
"#;

// ─── AddField ──────────────────────────────────────────────

#[test]
fn test_add_field_success() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::AddField {
        intent: "ShopWorld".into(),
        schema: "Product".into(),
        field_name: "discount".into(),
        field_type: FlType::F64,
        required: false,
    };
    let (ok, msg) = eng.apply(&mut graph, op);
    assert!(ok, "실패: {}", msg);
    let schema = graph.intents[0].schemas.iter().find(|s| s.name == "Product").unwrap();
    assert!(schema.fields.iter().any(|f| f.name == "discount"));
}

#[test]
fn test_add_field_required() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::AddField {
        intent: "ShopWorld".into(),
        schema: "Product".into(),
        field_name: "sku".into(),
        field_type: FlType::String,
        required: true,
    };
    let (ok, _) = eng.apply(&mut graph, op);
    assert!(ok);
    let schema = graph.intents[0].schemas.iter().find(|s| s.name == "Product").unwrap();
    let f = schema.fields.iter().find(|f| f.name == "sku").unwrap();
    assert!(f.annotations.iter().any(|a| matches!(a, world_engine::ast::Annotation::Required)));
}

#[test]
fn test_add_field_duplicate_fails() {
    let mut graph = parse(BASE_FL);
    let eng = MutationEngine::new();
    let op = MutationOp::AddField {
        intent: "ShopWorld".into(),
        schema: "Product".into(),
        field_name: "name".into(), // 이미 존재
        field_type: FlType::String,
        required: false,
    };
    let (ok, _) = eng.apply(&mut graph, op);
    assert!(!ok);
}

