    let op = MutationOp::AddField {
        intent: "NoSuchWorld".into(),
        schema: "Product".into(),
        field_name: "x".into(),
        field_type: FlType::I64,
        required: false,
    };
    let (ok, _) = eng.apply(&mut graph, op);
    assert!(!ok);
}

