use world_engine::emitter::{emit, EmitTarget};

fn parse(src: &str) -> world_engine::IntentGraph {
    world_engine::parse(src).expect("파싱 실패")
}

const BASE_FL: &str = r#"
intent ShopWorld {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Product {
        id: uuid @primary,
        name: string @required,
        price: f64 @required,
        qty: i64 @default(0),
        active: bool,
    }
    action restock(product_id: uuid, amount: i64) {
        update Product set qty = qty + amount where id == product_id;
        return amount;
    }
    action disable(product_id: uuid) {
        update Product set active = false where id == product_id;
        return product_id;
    }
    view ProductGrid {
        type: Grid,
        source: Product,
        interact: [restock],
    }
}
"#;

// ─── EmitTarget::from_str ─────────────────────────────────

#[test]
fn test_emit_target_typescript() {
    assert_eq!(world_engine::emitter::EmitTarget::from_str("ts"), Some(EmitTarget::TypeScript));
    assert_eq!(world_engine::emitter::EmitTarget::from_str("typescript"), Some(EmitTarget::TypeScript));
}

#[test]
fn test_emit_target_go() {
    assert_eq!(world_engine::emitter::EmitTarget::from_str("go"), Some(EmitTarget::Go));
    assert_eq!(world_engine::emitter::EmitTarget::from_str("golang"), Some(EmitTarget::Go));
}

#[test]
fn test_emit_target_sql() {
    assert_eq!(world_engine::emitter::EmitTarget::from_str("sql"), Some(EmitTarget::Sql));
}

#[test]
fn test_emit_target_openapi() {
    assert_eq!(world_engine::emitter::EmitTarget::from_str("openapi"), Some(EmitTarget::OpenApi));
    assert_eq!(world_engine::emitter::EmitTarget::from_str("yaml"), Some(EmitTarget::OpenApi));
}

#[test]
fn test_emit_target_unknown_is_none() {
    assert_eq!(world_engine::emitter::EmitTarget::from_str("ruby"), None);
    assert_eq!(world_engine::emitter::EmitTarget::from_str(""), None);
}

// ─── TypeScript ───────────────────────────────────────────

#[test]
fn test_ts_has_interface() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::TypeScript);
    assert!(out.contains("export interface Product"), "인터페이스 없음:\n{}", out);
}

#[test]
fn test_ts_primary_field_required() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::TypeScript);
    // @primary 필드는 optional(?) 아님
    assert!(out.contains("  id: string;"), "id 필드가 optional이면 안 됨:\n{}", out);
}

#[test]
fn test_ts_optional_field() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::TypeScript);
    // active는 @required/@primary 없으므로 optional
    assert!(out.contains("active?: boolean"), "active 필드가 optional이어야 함:\n{}", out);
}

#[test]
fn test_ts_type_mapping() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::TypeScript);
    assert!(out.contains("number"));  // f64, i64
    assert!(out.contains("string"));  // string, uuid
    assert!(out.contains("boolean")); // bool
}

#[test]
fn test_ts_async_function() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::TypeScript);
    assert!(out.contains("export async function restock"), "action 함수 없음:\n{}", out);
}

#[test]
fn test_ts_api_client() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::TypeScript);
    assert!(out.contains("shopWorldApi"), "API 클라이언트 없음:\n{}", out);
    assert!(out.contains("getAllProduct"), "getAllProduct 없음:\n{}", out);
}

#[test]
fn test_ts_api_client_action() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::TypeScript);
    assert!(out.contains("restock:"), "API 클라이언트에 action 없음:\n{}", out);
}

#[test]
fn test_ts_not_empty() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::TypeScript);
    assert!(out.len() > 100);
}

// ─── Go ───────────────────────────────────────────────────

#[test]
fn test_go_has_struct() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::Go);
    assert!(out.contains("type Product struct"), "Go 구조체 없음:\n{}", out);
}

#[test]
fn test_go_field_types() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::Go);
    assert!(out.contains("int64"),   "int64 없음");
    assert!(out.contains("float64"), "float64 없음");
    assert!(out.contains("string"),  "string 없음");
    assert!(out.contains("bool"),    "bool 없음");
}

#[test]
fn test_go_json_tags() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::Go);
    assert!(out.contains("`json:\""), "JSON 태그 없음:\n{}", out);
}

#[test]
fn test_go_service_interface() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::Go);
    assert!(out.contains("type ShopWorldService interface"), "서비스 인터페이스 없음:\n{}", out);
}

#[test]
fn test_go_optional_pointer() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::Go);
    // active는 optional → *bool
    assert!(out.contains("*bool"), "optional 포인터 없음:\n{}", out);
}

#[test]
fn test_go_has_package() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::Go);
    assert!(out.contains("package generated"));
}

// ─── SQL ──────────────────────────────────────────────────

#[test]
fn test_sql_create_table() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::Sql);
    assert!(out.contains("CREATE TABLE IF NOT EXISTS Product"), "CREATE TABLE 없음:\n{}", out);
}

#[test]
fn test_sql_primary_key() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::Sql);
    assert!(out.contains("PRIMARY KEY"), "@primary → PRIMARY KEY 없음:\n{}", out);
}

#[test]
fn test_sql_not_null() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::Sql);
    assert!(out.contains("NOT NULL"), "@required → NOT NULL 없음:\n{}", out);
}

#[test]
fn test_sql_default() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::Sql);
    assert!(out.contains("DEFAULT"), "@default → DEFAULT 없음:\n{}", out);
}

#[test]
fn test_sql_type_mapping() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::Sql);
    assert!(out.contains("TEXT"),    "TEXT 없음");
    assert!(out.contains("INTEGER"), "INTEGER 없음");
    assert!(out.contains("REAL"),    "REAL 없음");
}

// ─── OpenAPI ──────────────────────────────────────────────

#[test]
fn test_openapi_header() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::OpenApi);
    assert!(out.contains("openapi: 3.0.0"), "OpenAPI 헤더 없음:\n{}", out);
}

#[test]
fn test_openapi_paths() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::OpenApi);
    assert!(out.contains("/ShopWorld/Product"), "스키마 경로 없음:\n{}", out);
    assert!(out.contains("/ShopWorld/restock"), "action 경로 없음:\n{}", out);
}

#[test]
fn test_openapi_components() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::OpenApi);
    assert!(out.contains("components:"), "components 없음:\n{}", out);
    assert!(out.contains("$ref: '#/components/schemas/Product'"), "Product $ref 없음:\n{}", out);
}

#[test]
fn test_openapi_mutation_endpoint() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::OpenApi);
    assert!(out.contains("/mutate:"), "/mutate 엔드포인트 없음:\n{}", out);
    assert!(out.contains("/mutations:"), "/mutations 엔드포인트 없음:\n{}", out);
}

#[test]
fn test_openapi_required_fields() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::OpenApi);
    assert!(out.contains("required:"), "required 없음:\n{}", out);
}

#[test]
fn test_openapi_format_uuid() {
    let graph = parse(BASE_FL);
    let out = emit(&graph, EmitTarget::OpenApi);
    assert!(out.contains("format: uuid"), "uuid format 없음:\n{}", out);
}

// ─── router GET /emit ─────────────────────────────────────

#[test]
fn test_router_emit_typescript() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse(BASE_FL);
    let result = Synthesizer::synthesize(&graph);
    let mut router = Router::from_graph(graph);
    let (status, json) = router.handle(&mut { result.db }, "GET", "/emit/typescript", "");
    assert_eq!(status, 200);
    assert!(json["code"].as_str().unwrap().contains("export interface Product"));
}

#[test]
fn test_router_emit_sql() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse(BASE_FL);
    let result = Synthesizer::synthesize(&graph);
    let mut router = Router::from_graph(graph);
    let (status, json) = router.handle(&mut { result.db }, "GET", "/emit/sql", "");
    assert_eq!(status, 200);
    assert!(json["code"].as_str().unwrap().contains("CREATE TABLE"));
}

#[test]
fn test_router_emit_go() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse(BASE_FL);
    let result = Synthesizer::synthesize(&graph);
    let mut router = Router::from_graph(graph);
    let (status, json) = router.handle(&mut { result.db }, "GET", "/emit/go", "");
    assert_eq!(status, 200);
    assert!(json["code"].as_str().unwrap().contains("type Product struct"));
}

#[test]
fn test_router_emit_openapi() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse(BASE_FL);
    let result = Synthesizer::synthesize(&graph);
    let mut router = Router::from_graph(graph);
    let (status, json) = router.handle(&mut { result.db }, "GET", "/emit/openapi", "");
    assert_eq!(status, 200);
    assert!(json["code"].as_str().unwrap().contains("openapi: 3.0.0"));
    assert_eq!(json["content_type"].as_str().unwrap(), "yaml");
}

#[test]
fn test_router_emit_default_json() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse(BASE_FL);
    let result = Synthesizer::synthesize(&graph);
    let mut router = Router::from_graph(graph);
    let (status, json) = router.handle(&mut { result.db }, "GET", "/emit", "");
    assert_eq!(status, 200);
    assert_eq!(json["content_type"].as_str().unwrap(), "json");
}

#[test]
fn test_router_emit_lines_count() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse(BASE_FL);
    let result = Synthesizer::synthesize(&graph);
    let mut router = Router::from_graph(graph);
    let (_, json) = router.handle(&mut { result.db }, "GET", "/emit/typescript", "");
    let lines = json["lines"].as_u64().unwrap();
    assert!(lines > 10, "TypeScript 출력이 너무 짧음: {} lines", lines);
}

