pub mod codec;
pub mod router;
pub mod server;

use crate::ast::IntentGraph;
use crate::synthesizer::Synthesizer;
use router::Router;
use server::Server;

// ============================================================
// ActionBinder - Intent Graph → REST API 자동 바인딩
// ============================================================

pub struct ActionBinder {
    pub router: Router,
    pub server: Server,
}

impl ActionBinder {
    pub fn bind(graph: IntentGraph, port: u16) -> Self {
        let result = Synthesizer::synthesize(&graph);

        println!("{}", result.summary());

        let router = Router::from_graph(graph);
        let server = Server::new(
            Router::from_graph(router.graph.clone()),
            result.db,
            port,
        );

        ActionBinder { router, server }
    }

    pub fn start(self) -> std::io::Result<()> {
        println!("바인딩된 라우트:");
        for route in &self.router.routes {
            println!("  {} {}", route.method, route.path);
        }
        println!();
        self.server.start()
    }
}

