// ============================================================
// World Engine CLI - 서브커맨드 파서
// ============================================================

#[derive(Debug, PartialEq)]
pub enum CliCommand {
    /// world new <name>          — 새 .fl 프로젝트 스캐폴딩
    New { name: String },

    /// world run <file.fl> [--port N] [--hot]  — 서버 실행
    Run {
        path: String,
        port: u16,
        hot_reload: bool,
    },

    /// world build <file.fl> [--target ts|go|sql|openapi] [--out dir]
    Build {
        path: String,
        targets: Vec<String>,
        out_dir: String,
    },

    /// world emit <file.fl> <target>   — stdout 출력
    Emit { path: String, target: String },

    /// world validate <file.fl>
    Validate { path: String },

    /// world inspect <file.fl> [--deficiencies|--lifecycle|--routes]
    Inspect { path: String, aspect: InspectAspect },

    /// world help [subcommand]
    Help { topic: Option<String> },

    /// world version
    Version,
}

#[derive(Debug, PartialEq)]
pub enum InspectAspect {
    All,
    Deficiencies,
    Lifecycle,
    Routes,
    Views,
}

impl InspectAspect {
    fn from_flag(s: &str) -> Self {
        match s {
            "--deficiencies" | "-d" => InspectAspect::Deficiencies,
            "--lifecycle"    | "-l" => InspectAspect::Lifecycle,
            "--routes"       | "-r" => InspectAspect::Routes,
            "--views"        | "-v" => InspectAspect::Views,
            _                       => InspectAspect::All,
        }
    }
}

// ============================================================
// 파싱
// ============================================================

#[derive(Debug, PartialEq)]
pub struct ParseError(pub String);

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

pub fn parse_args(args: &[String]) -> Result<CliCommand, ParseError> {
    if args.is_empty() {
        return Ok(CliCommand::Help { topic: None });
    }

    match args[0].as_str() {
        "version" | "--version" | "-V" => Ok(CliCommand::Version),

        "help" | "--help" | "-h" => {
            let topic = args.get(1).cloned();
            Ok(CliCommand::Help { topic })
        }

        "new" => {
            let name = args.get(1)
                .ok_or_else(|| ParseError("world new <name>".into()))?
                .clone();
            Ok(CliCommand::New { name })
        }

        "run" => {
            let path = args.get(1)
                .ok_or_else(|| ParseError("world run <file.fl>".into()))?
                .clone();
            let mut port = 7777u16;
            let mut hot_reload = false;
            let mut i = 2;
            while i < args.len() {
                match args[i].as_str() {
                    "--port" | "-p" => {
                        i += 1;
                        port = args.get(i)
                            .and_then(|s| s.parse().ok())
                            .unwrap_or(7777);
                    }
                    "--hot" | "-H" => hot_reload = true,
                    _ => {}
                }
                i += 1;
            }
            Ok(CliCommand::Run { path, port, hot_reload })
        }

        "build" => {
            let path = args.get(1)
                .ok_or_else(|| ParseError("world build <file.fl>".into()))?
                .clone();
            let mut targets = Vec::new();
            let mut out_dir = "dist".to_string();
            let mut i = 2;
            while i < args.len() {
                match args[i].as_str() {
                    "--target" | "-t" => {
                        i += 1;
                        if let Some(t) = args.get(i) {
                            targets.push(t.clone());
                        }
                    }
                    "--out" | "-o" => {
                        i += 1;
                        if let Some(o) = args.get(i) {
                            out_dir = o.clone();
                        }
                    }
                    _ => {}
                }
                i += 1;
            }
            // 기본 타겟: 전부
            if targets.is_empty() {
                targets = vec![
                    "typescript".into(),
                    "go".into(),
                    "sql".into(),
                    "openapi".into(),
                ];
            }
            Ok(CliCommand::Build { path, targets, out_dir })
        }

        "emit" => {
            let path = args.get(1)
                .ok_or_else(|| ParseError("world emit <file.fl> <target>".into()))?
                .clone();
            let target = args.get(2)
                .ok_or_else(|| ParseError("world emit <file.fl> <target> (ts|go|sql|openapi)".into()))?
                .clone();
            Ok(CliCommand::Emit { path, target })
        }

        "validate" => {
            let path = args.get(1)
                .ok_or_else(|| ParseError("world validate <file.fl>".into()))?
                .clone();
            Ok(CliCommand::Validate { path })
        }

        "inspect" => {
            let path = args.get(1)
                .ok_or_else(|| ParseError("world inspect <file.fl>".into()))?
                .clone();
            let aspect = args.get(2)
                .map(|s| InspectAspect::from_flag(s))
                .unwrap_or(InspectAspect::All);
            Ok(CliCommand::Inspect { path, aspect })
        }

        other => Err(ParseError(format!(
            "알 수 없는 커맨드: '{}'\n'world help'를 실행하세요.", other
        ))),
    }
}

// ============================================================
// 도움말 텍스트
// ============================================================

pub const VERSION: &str = env!("CARGO_PKG_VERSION");

pub fn help_text(topic: Option<&str>) -> String {
    match topic {
        None => format!(
r#"World Engine v{} — Intent-Driven Computing

사용법: world <command> [options]

Commands:
  new <name>          새 .fl 프로젝트 스캐폴딩
  run <file.fl>       REST API 서버 실행
  build <file.fl>     코드 생성 (TS/Go/SQL/OpenAPI)
  emit <file.fl> <t>  stdout에 코드 출력
  validate <file.fl>  DSL 문법 + 구조 검증
  inspect <file.fl>   Intent Graph 분석 리포트
  version             버전 정보
  help [command]      도움말

'world help <command>' 로 상세 도움말 확인
"#,
            VERSION
        ),

        Some("run") => String::from(
r#"world run <file.fl> [options]

