#[test]
fn test_inspect_short_flags() {
    assert_eq!(
        parse_args(&args(&["inspect", "shop.fl", "-d"])).unwrap(),
        CliCommand::Inspect { path: "shop.fl".into(), aspect: InspectAspect::Deficiencies }
    );
    assert_eq!(
        parse_args(&args(&["inspect", "shop.fl", "-r"])).unwrap(),
        CliCommand::Inspect { path: "shop.fl".into(), aspect: InspectAspect::Routes }
    );
}

#[test]
fn test_inspect_missing_file() {
    assert!(parse_args(&args(&["inspect"])).is_err());
}

// ─── 알 수 없는 커맨드 ────────────────────────────────────

#[test]
fn test_unknown_command_error() {
    assert!(parse_args(&args(&["fly"])).is_err());
}

#[test]
fn test_unknown_command_error_message() {
    let e = parse_args(&args(&["fly"])).unwrap_err();
    assert!(e.to_string().contains("fly"), "오류 메시지에 커맨드명 없음: {}", e);
}

// ─── world new 스캐폴딩 파일 내용 ─────────────────────────

#[test]
fn test_new_scaffold_creates_files() {
    use std::fs;
    let name = format!("test_new_scaffold_{}", std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH).unwrap().as_secs());
    let dir = std::path::PathBuf::from(&name);

    // 디렉토리 생성 + 파일 직접 생성 (cmd_new 로직 복제)
    fs::create_dir_all(&dir).unwrap();
    let pascal: String = name.split(|c: char| c == '-' || c == '_').map(|w| {
        let mut c = w.chars();
        match c.next() { None => String::new(), Some(f) => f.to_uppercase().to_string() + c.as_str() }
    }).collect();
    let fl = format!("intent {} {{\n}}\n", pascal);
    let readme = format!("# {}\n", name);
    fs::write(dir.join("main.fl"), &fl).unwrap();
    fs::write(dir.join("README.md"), &readme).unwrap();

    assert!(dir.join("main.fl").exists());
    assert!(dir.join("README.md").exists());

    // 정리
    fs::remove_dir_all(&dir).unwrap();
}

