   128→            .map(|t| t.columns.iter().collect())
   129→            .unwrap_or_default()
   130→    }
   131→
   132→    fn gen_uuid(&mut self) -> String {
   133→        let id = self.uuid_seq;
   134→        self.uuid_seq += 1;
   135→        format!("{:08x}-0000-0000-0000-{:012x}", id, id)
