   234→        C: Fn(&Row) -> bool,
   235→        V: Fn(&Row) -> Vec<(String, Value)>,
   236→    {
   237→        let table = self.tables.get_mut(table_name)
   238→            .ok_or_else(|| DbError::TableNotFound(table_name.to_string()))?;
   239→
   240→        let mut count = 0;
   241→        for row in table.rows.iter_mut() {
   242→            if condition(row) {
   243→                for (field, value) in compute(row) {
   244→                    row.insert(field, value);
   245→                }
