   257→        }
   258→    }
   259→
   260→    // ─── DELETE ───────────────────────────────────────────────
   261→
   262→    pub fn delete<F>(&mut self, table_name: &str, condition: F) -> Result<usize, DbError>
   263→    where
   264→        F: Fn(&Row) -> bool,
   265→    {
