use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::SystemTime;
use crate::synthesizer::kimdb::{KimDB, Value, Row};
use crate::binder::codec::value_to_json;

// ============================================================
// Snapshot - KimDB 직렬화 포맷
// ============================================================

// Value → serde_json::Value (타입 태그 포함)
fn value_to_tagged(val: &Value) -> serde_json::Value {
    match val {
        Value::Int(n)   => serde_json::json!({ "t": "i", "v": n }),
        Value::Float(f) => serde_json::json!({ "t": "f", "v": f }),
        Value::Str(s)   => serde_json::json!({ "t": "s", "v": s }),
        Value::Bool(b)  => serde_json::json!({ "t": "b", "v": b }),
        Value::Uuid(u)  => serde_json::json!({ "t": "u", "v": u }),
        Value::Null     => serde_json::json!({ "t": "n" }),
    }
}

fn tagged_to_value(json: &serde_json::Value) -> Value {
    let t = json["t"].as_str().unwrap_or("n");
    match t {
        "i" => json["v"].as_i64().map(Value::Int).unwrap_or(Value::Null),
        "f" => json["v"].as_f64().map(Value::Float).unwrap_or(Value::Null),
        "s" => json["v"].as_str().map(|s| Value::Str(s.into())).unwrap_or(Value::Null),
        "b" => json["v"].as_bool().map(Value::Bool).unwrap_or(Value::Null),
        "u" => json["v"].as_str().map(|s| Value::Uuid(s.into())).unwrap_or(Value::Null),
        _   => Value::Null,
    }
}

pub fn row_to_snapshot(row: &Row) -> serde_json::Value {
    let mut keys: Vec<&String> = row.keys().collect();
    keys.sort();
    let map: serde_json::Map<String, serde_json::Value> = keys.iter()
        .map(|k| ((*k).clone(), value_to_tagged(&row[*k])))
        .collect();
    serde_json::Value::Object(map)
}

pub fn snapshot_to_row(json: &serde_json::Value) -> Row {
    let mut row = HashMap::new();
    if let Some(obj) = json.as_object() {
        for (k, v) in obj {
            row.insert(k.clone(), tagged_to_value(v));
        }
    }
    row
}

// ============================================================
// KimDB 스냅샷 확장 메서드
// ============================================================

impl KimDB {
    /// 현재 DB 상태를 JSON 스냅샷으로 직렬화
    pub fn to_snapshot(&self) -> serde_json::Value {
        let tables: serde_json::Value = serde_json::Value::Object(
            self.table_names().iter().map(|name| {
                let rows: Vec<serde_json::Value> = self.select_all(name)
                    .unwrap_or_default()
                    .iter()
                    .map(|r| row_to_snapshot(r))
                    .collect();
                (name.clone(), serde_json::json!({
                    "rows": rows,
                    "count": rows.len(),
                }))
            }).collect()
        );

        let ts = SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();

        serde_json::json!({
            "version": 1,
            "saved_at": ts,
            "tables": tables,
        })
    }

    /// JSON 스냅샷으로부터 rows 복원
    /// (provision()으로 스키마가 이미 세팅된 상태에서 호출)
    pub fn apply_snapshot(&mut self, snapshot: &serde_json::Value) -> Result<usize, String> {
        let tables = snapshot["tables"].as_object()
            .ok_or("스냅샷에 'tables' 필드 없음")?;

        let mut total = 0usize;
        for (table_name, table_data) in tables {
            let rows = match table_data["rows"].as_array() {
                Some(r) => r,
                None    => continue,
            };
            for row_json in rows {
                let row = snapshot_to_row(row_json);
                match self.insert_raw(table_name, row) {
                    Ok(_) => total += 1,
                    Err(e) => eprintln!("[persist] insert_raw 실패 '{}': {}", table_name, e),
                }
            }
        }
        Ok(total)
    }

    /// row를 검증 없이 직접 삽입 (스냅샷 복원 전용)
    pub fn insert_raw(&mut self, table_name: &str, row: Row) -> Result<(), String> {
        let table = self.tables.get_mut(table_name)
            .ok_or_else(|| format!("테이블 없음: '{}'", table_name))?;
        table.rows.push(row);
        Ok(())
    }
}

