}

#[test]
fn test_base64url_url_safe() {
    use world_engine::auth::token::base64url_encode;
    let encoded = base64url_encode(b"test data with various bytes \x00\xff");
    assert!(!encoded.contains('+'));
    assert!(!encoded.contains('/'));
