use std::time::SystemTime;
use crate::auth::apikey::Permission;

// ============================================================
// JWT-like 토큰 (외부 crate 없이)
// 구조: base64url(header).base64url(payload).signature
// 서명: FNV-1a64(secret + "." + header + "." + payload)
// ============================================================

#[derive(Debug, Clone, PartialEq)]
pub enum TokenError {
    Malformed,
    InvalidSignature,
    Expired,
    Revoked,
}

impl std::fmt::Display for TokenError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            TokenError::Malformed          => write!(f, "토큰 형식 오류"),
            TokenError::InvalidSignature   => write!(f, "서명 불일치"),
            TokenError::Expired            => write!(f, "토큰 만료"),
            TokenError::Revoked            => write!(f, "폐기된 토큰"),
        }
    }
}

#[derive(Debug, Clone)]
pub struct TokenClaims {
    pub sub: String,        // subject (사용자/키 이름)
    pub permission: Permission,
    pub iat: u64,           // issued at (unix secs)
    pub exp: u64,           // expires at (unix secs)
    pub jti: String,        // JWT ID (고유 식별자)
}

pub struct AuthToken {
    pub claims: TokenClaims,
}

impl AuthToken {
    pub fn new(subject: &str, permission: Permission, ttl_secs: u64, _secret: &str) -> Self {
        let now = unix_now();
        let jti = format!("{:x}-{:x}", now, fnv1a64(subject.as_bytes()));
        AuthToken {
            claims: TokenClaims {
                sub: subject.to_string(),
                permission,
                iat: now,
                exp: now + ttl_secs,
                jti,
            },
        }
    }

    /// 토큰 인코딩: base64url(payload).signature
    pub fn encode(&self) -> String {
        let payload = serde_json::json!({
            "sub": self.claims.sub,
            "perm": self.claims.permission.as_str(),
            "iat": self.claims.iat,
            "exp": self.claims.exp,
            "jti": self.claims.jti,
        }).to_string();

        let encoded = base64url_encode(payload.as_bytes());
        // 헤더는 고정
        let header = base64url_encode(b"{\"alg\":\"FNV64\",\"typ\":\"WE\"}");
        let sig = make_signature(&header, &encoded);
        format!("{}.{}.{}", header, encoded, sig)
    }

    /// 토큰 디코딩 + 검증
    pub fn decode(raw: &str, _secret: &str) -> Result<TokenClaims, TokenError> {
        let parts: Vec<&str> = raw.splitn(3, '.').collect();
        if parts.len() != 3 {
            return Err(TokenError::Malformed);
        }
        let (header, payload_b64, sig) = (parts[0], parts[1], parts[2]);

        // 서명 검증
        let expected_sig = make_signature(header, payload_b64);
        if sig != expected_sig {
            return Err(TokenError::InvalidSignature);
        }

        // payload 디코딩
        let payload_bytes = base64url_decode(payload_b64)
            .ok_or(TokenError::Malformed)?;
        let payload_str = std::str::from_utf8(&payload_bytes)
            .map_err(|_| TokenError::Malformed)?;
        let json: serde_json::Value = serde_json::from_str(payload_str)
            .map_err(|_| TokenError::Malformed)?;

        let sub  = json["sub"].as_str().ok_or(TokenError::Malformed)?.to_string();
        let perm = json["perm"].as_str().ok_or(TokenError::Malformed)?;
        let iat  = json["iat"].as_u64().ok_or(TokenError::Malformed)?;
        let exp  = json["exp"].as_u64().ok_or(TokenError::Malformed)?;
        let jti  = json["jti"].as_str().ok_or(TokenError::Malformed)?.to_string();

        // 만료 확인
        let now = unix_now();
        if now > exp {
            return Err(TokenError::Expired);
        }

        Ok(TokenClaims {
            sub,
            permission: Permission::from_str(perm),
            iat, exp, jti,
        })
    }
}

// ============================================================
// 내부 유틸
// ============================================================

fn unix_now() -> u64 {
    SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

/// FNV-1a 64bit 해시
fn fnv1a64(data: &[u8]) -> u64 {
    let mut hash: u64 = 0xcbf29ce484222325;
    for &b in data {
        hash ^= b as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    }
    hash
}

/// 서명 생성: FNV-1a64(header + "." + payload) → hex
fn make_signature(header: &str, payload: &str) -> String {
    let mut data = Vec::with_capacity(header.len() + 1 + payload.len());
    data.extend_from_slice(header.as_bytes());
    data.push(b'.');
    data.extend_from_slice(payload.as_bytes());
    // 두 번 해시로 강도 높임
    let h1 = fnv1a64(&data);
    let h2 = fnv1a64(&h1.to_le_bytes());
    format!("{:016x}{:016x}", h1, h2)
}

/// URL-safe base64 인코딩 (패딩 없음)
pub fn base64url_encode(input: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    let mut out = String::new();
    let mut i = 0;
    while i < input.len() {
        let b0 = input[i] as u32;
        let b1 = if i + 1 < input.len() { input[i + 1] as u32 } else { 0 };
        let b2 = if i + 2 < input.len() { input[i + 2] as u32 } else { 0 };
        out.push(CHARS[((b0 >> 2) & 0x3f) as usize] as char);
        out.push(CHARS[(((b0 << 4) | (b1 >> 4)) & 0x3f) as usize] as char);
        if i + 1 < input.len() {
            out.push(CHARS[(((b1 << 2) | (b2 >> 6)) & 0x3f) as usize] as char);
        }
        if i + 2 < input.len() {
            out.push(CHARS[(b2 & 0x3f) as usize] as char);
        }
        i += 3;
    }
    out
}

/// URL-safe base64 디코딩 (패딩 없음)
pub fn base64url_decode(input: &str) -> Option<Vec<u8>> {
    let decode_char = |c: u8| -> Option<u8> {
        match c {
            b'A'..=b'Z' => Some(c - b'A'),
            b'a'..=b'z' => Some(c - b'a' + 26),
            b'0'..=b'9' => Some(c - b'0' + 52),
            b'-'        => Some(62),
            b'_'        => Some(63),
            _           => None,
        }
    };

    let bytes: Vec<u8> = input.bytes().collect();
    let mut out = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        let c0 = decode_char(bytes[i])?;
        let c1 = if i + 1 < bytes.len() { decode_char(bytes[i + 1])? } else { 0 };
        let c2 = if i + 2 < bytes.len() { decode_char(bytes[i + 2])? } else { 0 };
        let c3 = if i + 3 < bytes.len() { decode_char(bytes[i + 3])? } else { 0 };

        out.push((c0 << 2) | (c1 >> 4));
        if i + 2 < bytes.len() { out.push((c1 << 4) | (c2 >> 2)); }
        if i + 3 < bytes.len() { out.push((c2 << 6) | c3); }
        i += 4;
    }
    Some(out)
}

