fn unix_now() -> u64 {
    SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

/// FNV-1a 64bit 해시
fn fnv1a64(data: &[u8]) -> u64 {
    let mut hash: u64 = 0xcbf29ce484222325;
    for &b in data {
        hash ^= b as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    }
    hash
}

/// 서명 생성: FNV-1a64(header + "." + payload) → hex
fn make_signature(header: &str, payload: &str) -> String {
    let mut data = Vec::with_capacity(header.len() + 1 + payload.len());
    data.extend_from_slice(header.as_bytes());
    data.push(b'.');
    data.extend_from_slice(payload.as_bytes());
    // 두 번 해시로 강도 높임
    let h1 = fnv1a64(&data);
    let h2 = fnv1a64(&h1.to_le_bytes());
    format!("{:016x}{:016x}", h1, h2)
}

