pub mod apikey;
pub mod token;
pub mod middleware;

pub use apikey::{ApiKey, ApiKeyStore, Permission};
pub use token::{AuthToken, TokenClaims, TokenError};
pub use middleware::{AuthMiddleware, AuthResult, AuthConfig};

// ============================================================
// AuthManager - API Key + Token 통합 관리
// ============================================================

use std::sync::Mutex;
use std::collections::HashMap;

pub struct AuthManager {
    pub config: AuthConfig,
    pub key_store: Mutex<ApiKeyStore>,
    /// 발급된 토큰 블랙리스트 (로그아웃 / 강제 만료)
    pub revoked: Mutex<std::collections::HashSet<String>>,
}

impl AuthManager {
    pub fn new(config: AuthConfig) -> Self {
        AuthManager {
            config,
            key_store: Mutex::new(ApiKeyStore::new()),
            revoked: Mutex::new(Default::default()),
        }
    }

    /// API Key 발급
    pub fn issue_api_key(&self, label: &str, permission: Permission) -> String {
        let key = ApiKey::generate(label, permission);
        let raw = key.raw.clone();
        self.key_store.lock().unwrap().add(key);
        raw
    }

    /// 요청 헤더에서 인증 검증
    pub fn authenticate(&self, headers: &HashMap<String, String>) -> AuthResult {
        AuthMiddleware::authenticate(self, headers)
    }

    /// 토큰 발급 (인증된 클라이언트에게)
    pub fn issue_token(&self, subject: &str, permission: Permission) -> String {
        AuthToken::new(subject, permission, self.config.token_ttl_secs, &self.config.secret)
            .encode()
    }

    /// 토큰 검증
    pub fn verify_token(&self, raw: &str) -> Result<TokenClaims, TokenError> {
        let claims = AuthToken::decode(raw, &self.config.secret)?;
        // 블랙리스트 확인
        if self.revoked.lock().unwrap().contains(&claims.jti) {
            return Err(TokenError::Revoked);
        }
        Ok(claims)
    }

    /// 토큰 폐기 (로그아웃)
    pub fn revoke_token(&self, raw: &str) {
        if let Ok(claims) = AuthToken::decode(raw, &self.config.secret) {
            self.revoked.lock().unwrap().insert(claims.jti);
        }
    }

    pub fn status_json(&self) -> serde_json::Value {
        let store = self.key_store.lock().unwrap();
        let revoked_count = self.revoked.lock().unwrap().len();
        serde_json::json!({
            "enabled": true,
            "api_keys": store.count(),
            "revoked_tokens": revoked_count,
            "token_ttl_secs": self.config.token_ttl_secs,
            "public_paths": self.config.public_paths,
        })
    }
}

