use std::collections::{HashMap, VecDeque};
use std::sync::Mutex;
use std::time::{SystemTime, UNIX_EPOCH};

// ============================================================
// RateLimitConfig - 슬라이딩 윈도우 설정
// ============================================================

#[derive(Debug, Clone)]
pub struct RateLimitConfig {
    /// 슬라이딩 윈도우 크기 (초)
    pub window_secs: u64,
    /// ReadOnly 키 최대 요청 수 (윈도우당)
    pub readonly_limit: u64,
    /// ReadWrite 키 최대 요청 수
    pub readwrite_limit: u64,
    /// Admin 키 최대 요청 수
    pub admin_limit: u64,
}

impl Default for RateLimitConfig {
    fn default() -> Self {
        RateLimitConfig {
            window_secs:       60,
            readonly_limit:    60,
            readwrite_limit:  120,
            admin_limit:      600,
        }
    }
}

impl RateLimitConfig {
    pub fn new(window_secs: u64, readonly: u64, readwrite: u64, admin: u64) -> Self {
        RateLimitConfig {
            window_secs,
            readonly_limit:  readonly,
            readwrite_limit: readwrite,
            admin_limit:     admin,
        }
    }

    /// Permission에 맞는 한도 반환
    pub fn limit_for(&self, perm: &super::apikey::Permission) -> u64 {
        use super::apikey::Permission;
        match perm {
            Permission::ReadOnly  => self.readonly_limit,
            Permission::ReadWrite => self.readwrite_limit,
            Permission::Admin     => self.admin_limit,
        }
    }
}

// ============================================================
// RateLimitStatus - 검사 결과
// ============================================================

#[derive(Debug, Clone, PartialEq)]
pub struct RateLimitStatus {
    pub allowed:     bool,
    pub limit:       u64,
    pub remaining:   u64,
    pub used:        u64,
    /// 윈도우 리셋까지 남은 초
    pub reset_secs:  u64,
}

impl RateLimitStatus {
    pub fn to_headers(&self) -> Vec<(String, String)> {
        vec![
            ("X-RateLimit-Limit".into(),     self.limit.to_string()),
            ("X-RateLimit-Remaining".into(), self.remaining.to_string()),
            ("X-RateLimit-Reset".into(),     self.reset_secs.to_string()),
        ]
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "allowed":    self.allowed,
            "limit":      self.limit,
            "remaining":  self.remaining,
            "used":       self.used,
            "reset_secs": self.reset_secs,
        })
    }
}

// ============================================================
// RateLimiter - 슬라이딩 윈도우 구현 (외부 crate 없음)
// ============================================================

pub struct RateLimiter {
    pub config: RateLimitConfig,
    /// key → 요청 시각 큐 (unix secs)
    windows: Mutex<HashMap<String, VecDeque<u64>>>,
}

impl RateLimiter {
    pub fn new(config: RateLimitConfig) -> Self {
        RateLimiter {
            config,
            windows: Mutex::new(HashMap::new()),
        }
    }

    /// 요청 허용 여부 확인 + 허용 시 카운트 증가
    pub fn check(&self, key: &str, limit: u64) -> RateLimitStatus {
        let now    = unix_now();
        let cutoff = now.saturating_sub(self.config.window_secs);

        let mut map   = self.windows.lock().unwrap();
        let deque = map.entry(key.to_string()).or_insert_with(VecDeque::new);

        // 윈도우 밖 요청 제거
        while deque.front().copied().map_or(false, |t| t <= cutoff) {
            deque.pop_front();
        }

        let used = deque.len() as u64;

        if used >= limit {
            // 가장 오래된 요청 기준으로 리셋 시간 계산
            let oldest     = deque.front().copied().unwrap_or(now);
            let reset_secs = oldest
                .saturating_add(self.config.window_secs)
                .saturating_sub(now)
                .max(1);
            RateLimitStatus {
                allowed: false,
                limit,
                remaining: 0,
                used,
                reset_secs,
            }
        } else {
            deque.push_back(now);
            RateLimitStatus {
                allowed:    true,
                limit,
                remaining:  limit - used - 1,
                used:       used + 1,
                reset_secs: self.config.window_secs,
            }
        }
    }

    /// 현재 사용량 조회 (카운트 증가 없음)
    pub fn peek(&self, key: &str, limit: u64) -> RateLimitStatus {
        let now    = unix_now();
        let cutoff = now.saturating_sub(self.config.window_secs);

        let mut map   = self.windows.lock().unwrap();
        let deque = map.entry(key.to_string()).or_insert_with(VecDeque::new);

        while deque.front().copied().map_or(false, |t| t <= cutoff) {
            deque.pop_front();
        }

        let used = deque.len() as u64;
        let reset_secs = deque
            .front()
            .copied()
            .map(|t| t.saturating_add(self.config.window_secs).saturating_sub(now).max(1))
            .unwrap_or(self.config.window_secs);

        RateLimitStatus {
            allowed:   used < limit,
            limit,
            remaining: limit.saturating_sub(used),
            used,
            reset_secs,
        }
    }

    /// 전체 키 현재 윈도우 사용량
    pub fn all_stats(&self) -> HashMap<String, u64> {
        let now    = unix_now();
        let cutoff = now.saturating_sub(self.config.window_secs);

        let mut map = self.windows.lock().unwrap();
        map.iter_mut()
            .map(|(k, deque)| {
                while deque.front().copied().map_or(false, |t| t <= cutoff) {
                    deque.pop_front();
                }
                (k.clone(), deque.len() as u64)
            })
            .collect()
    }

    /// 특정 키 초기화 (관리자 강제 해제)
    pub fn reset_key(&self, key: &str) {
        self.windows.lock().unwrap().remove(key);
    }

    /// 전체 초기화
    pub fn reset_all(&self) {
        self.windows.lock().unwrap().clear();
    }
}

// ============================================================
// 내부 유틸
// ============================================================

fn unix_now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

