use std::sync::Arc;
use std::collections::HashMap;
use world_engine::auth::{
    AuthManager, RateLimiter, RateLimitConfig,
    middleware::AuthConfig,
    apikey::Permission,
};

fn make_rl(window: u64, ro: u64, rw: u64, admin: u64) -> RateLimiter {
    RateLimiter::new(RateLimitConfig::new(window, ro, rw, admin))
}

fn make_manager_with_rl(window: u64, limit: u64) -> AuthManager {
    AuthManager::new(AuthConfig::new("secret"))
        .with_rate_limit(RateLimitConfig::new(window, limit, limit * 2, limit * 10))
}

fn headers(pairs: &[(&str, &str)]) -> HashMap<String, String> {
    pairs.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect()
}

// ─── RateLimitConfig ───────────────────────────────────────

#[test]
fn test_config_default() {
    let cfg = RateLimitConfig::default();
    assert_eq!(cfg.window_secs, 60);
    assert_eq!(cfg.readonly_limit, 60);
    assert_eq!(cfg.readwrite_limit, 120);
    assert_eq!(cfg.admin_limit, 600);
}

#[test]
fn test_config_limit_for_permission() {
    let cfg = RateLimitConfig::new(60, 10, 20, 100);
    assert_eq!(cfg.limit_for(&Permission::ReadOnly), 10);
    assert_eq!(cfg.limit_for(&Permission::ReadWrite), 20);
    assert_eq!(cfg.limit_for(&Permission::Admin), 100);
}

// ─── RateLimiter 기본 동작 ─────────────────────────────────

#[test]
fn test_allow_within_limit() {
    let rl = make_rl(60, 3, 6, 30);
    for _ in 0..3 {
        let s = rl.check("key1", 3);
        assert!(s.allowed);
    }
}

#[test]
fn test_block_over_limit() {
    let rl = make_rl(60, 3, 6, 30);
    for _ in 0..3 {
        rl.check("key1", 3);
    }
    let s = rl.check("key1", 3);
    assert!(!s.allowed);
    assert_eq!(s.remaining, 0);
}

#[test]
fn test_remaining_decrements() {
    let rl = make_rl(60, 5, 10, 50);
    let s0 = rl.check("k", 5);
    assert_eq!(s0.remaining, 4);
    let s1 = rl.check("k", 5);
    assert_eq!(s1.remaining, 3);
    let s2 = rl.check("k", 5);
    assert_eq!(s2.remaining, 2);
}

#[test]
fn test_used_increments() {
    let rl = make_rl(60, 10, 20, 100);
    let s1 = rl.check("u", 10);
    assert_eq!(s1.used, 1);
    let s2 = rl.check("u", 10);
    assert_eq!(s2.used, 2);
}

#[test]
fn test_different_keys_independent() {
    let rl = make_rl(60, 2, 4, 20);
    rl.check("a", 2);
    rl.check("a", 2);
    // "a" 한도 초과
    assert!(!rl.check("a", 2).allowed);
    // "b"는 영향 없음
    assert!(rl.check("b", 2).allowed);
}

#[test]
fn test_limit_zero_always_blocks() {
    let rl = make_rl(60, 0, 0, 0);
    assert!(!rl.check("x", 0).allowed);
}

#[test]
fn test_reset_key() {
    let rl = make_rl(60, 2, 4, 20);
    rl.check("r", 2);
    rl.check("r", 2);
    assert!(!rl.check("r", 2).allowed);
    rl.reset_key("r");
    assert!(rl.check("r", 2).allowed);
}

#[test]
fn test_reset_all() {
    let rl = make_rl(60, 2, 4, 20);
    rl.check("a", 2); rl.check("a", 2);
    rl.check("b", 2); rl.check("b", 2);
    assert!(!rl.check("a", 2).allowed);
    assert!(!rl.check("b", 2).allowed);
    rl.reset_all();
    assert!(rl.check("a", 2).allowed);
    assert!(rl.check("b", 2).allowed);
}

#[test]
fn test_peek_does_not_increment() {
    let rl = make_rl(60, 5, 10, 50);
    let p1 = rl.peek("p", 5);
    let p2 = rl.peek("p", 5);
    assert_eq!(p1.used, p2.used);
    assert_eq!(p1.remaining, p2.remaining);
}

#[test]
fn test_stats_returns_all_keys() {
    let rl = make_rl(60, 10, 20, 100);
    rl.check("aa", 10);
    rl.check("bb", 10);
    rl.check("bb", 10);
    let stats = rl.all_stats();
    assert_eq!(*stats.get("aa").unwrap(), 1);
    assert_eq!(*stats.get("bb").unwrap(), 2);
}

#[test]
fn test_rate_limit_status_to_json() {
    let rl = make_rl(60, 5, 10, 50);
    let s = rl.check("j", 5);
    let j = s.to_json();
    assert_eq!(j["allowed"].as_bool().unwrap(), true);
    assert_eq!(j["limit"].as_u64().unwrap(), 5);
    assert!(j["remaining"].as_u64().is_some());
}

#[test]
fn test_rate_limit_status_to_headers() {
    let rl = make_rl(60, 5, 10, 50);
    let s = rl.check("h", 5);
    let hdrs = s.to_headers();
    assert!(hdrs.iter().any(|(k, _)| k == "X-RateLimit-Limit"));
    assert!(hdrs.iter().any(|(k, _)| k == "X-RateLimit-Remaining"));
    assert!(hdrs.iter().any(|(k, _)| k == "X-RateLimit-Reset"));
}

// ─── AuthManager 통합 ─────────────────────────────────────

#[test]
fn test_check_rate_limit_none_when_disabled() {
    let am = AuthManager::new(AuthConfig::new("s"));
    let result = am.check_rate_limit("key", &Permission::ReadOnly);
    assert!(result.is_none());
}

#[test]
fn test_check_rate_limit_allows_when_enabled() {
    let am = make_manager_with_rl(60, 10);
    let s = am.check_rate_limit("k", &Permission::ReadOnly).unwrap();
    assert!(s.allowed);
}

#[test]
fn test_check_rate_limit_blocks_over_limit() {
    let am = make_manager_with_rl(60, 2);
    am.check_rate_limit("k", &Permission::ReadOnly);
    am.check_rate_limit("k", &Permission::ReadOnly);
    let s = am.check_rate_limit("k", &Permission::ReadOnly).unwrap();
    assert!(!s.allowed);
}

#[test]
fn test_rate_limit_stats_json_disabled() {
    let am = AuthManager::new(AuthConfig::new("s"));
    let j = am.rate_limit_stats_json();
    assert_eq!(j["enabled"].as_bool().unwrap(), false);
}

#[test]
fn test_rate_limit_stats_json_enabled() {
    let am = make_manager_with_rl(60, 10);
    am.check_rate_limit("k1", &Permission::ReadOnly);
    let j = am.rate_limit_stats_json();
    assert_eq!(j["enabled"].as_bool().unwrap(), true);
    assert!(j["window_secs"].as_u64().is_some());
    assert!(j["current_usage"]["k1"].as_u64().is_some());
}

#[test]
fn test_status_json_shows_rate_limiting_field() {
    let am = make_manager_with_rl(60, 10);
    let j = am.status_json();
    assert_eq!(j["rate_limiting"].as_bool().unwrap(), true);
}

// ─── Router 엔드포인트 ─────────────────────────────────────

fn parse_fl() -> world_engine::IntentGraph {
    world_engine::parse(r#"
intent Shop {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Item { id: uuid @primary, name: string @required, }
    action list() { return 0; }
}
"#).unwrap()
}

#[test]
fn test_router_429_when_rate_limited() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse_fl();
    let result = Synthesizer::synthesize(&graph);
    let am = Arc::new(
        AuthManager::new(AuthConfig::new("secret"))
            .with_rate_limit(RateLimitConfig::new(60, 2, 4, 20))
    );
    let rw_key = am.issue_api_key("bot", Permission::ReadWrite);
    let mut router = Router::from_graph(graph).with_auth(Arc::clone(&am));
    let hdrs = headers(&[("x-api-key", &rw_key)]);

    // 한도(4)까지 요청
    for _ in 0..4 {
        let (s, _) = router.handle_with_headers(
            &mut { result.db.clone() }, "POST", "/mutate",
            r#"{"op":"add_field","intent":"Shop","schema":"Item","field_name":"price","field_type":"f64"}"#,
            &hdrs,
        );
        assert_ne!(s, 429, "한도 내 요청이 차단됨");
    }

    // 5번째: 429
    let (status, json) = router.handle_with_headers(
        &mut { result.db.clone() }, "POST", "/mutate",
        r#"{"op":"add_field","intent":"Shop","schema":"Item","field_name":"qty","field_type":"u32"}"#,
        &hdrs,
    );
    assert_eq!(status, 429, "한도 초과 요청이 허용됨: {:?}", json);
    assert!(json["error"].as_str().is_some());
    assert!(json["reset_secs"].as_u64().is_some());
}

#[test]
fn test_router_ratelimit_stats_endpoint() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse_fl();
    let result = Synthesizer::synthesize(&graph);
    let am = Arc::new(
        AuthManager::new(AuthConfig::new("secret"))
            .with_rate_limit(RateLimitConfig::default())
    );
    let mut router = Router::from_graph(graph).with_auth(Arc::clone(&am));
    let (status, json) = router.handle(
        &mut { result.db }, "GET", "/auth/ratelimit", ""
    );
    assert_eq!(status, 200);
    assert_eq!(json["enabled"].as_bool().unwrap(), true);
}

#[test]
fn test_router_ratelimit_disabled_returns_false() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = parse_fl();
    let result = Synthesizer::synthesize(&graph);
    let am = Arc::new(AuthManager::new(AuthConfig::new("secret")));
    let mut router = Router::from_graph(graph).with_auth(Arc::clone(&am));
    let (status, json) = router.handle(
        &mut { result.db }, "GET", "/auth/ratelimit", ""
    );
    assert_eq!(status, 200);
    assert_eq!(json["enabled"].as_bool().unwrap(), false);
}

use std::collections::{HashMap, HashSet};
use crate::auth::apikey::Permission;
use crate::auth::AuthManager;

// ============================================================
// AuthConfig - 인증 설정
// ============================================================

#[derive(Debug, Clone)]
pub struct AuthConfig {
    pub secret: String,
    pub token_ttl_secs: u64,
    /// 인증 없이 접근 가능한 경로 접두사
    pub public_paths: Vec<String>,
    /// 읽기 전용 경로 (ReadOnly 권한으로 충분)
    pub readonly_paths: Vec<String>,
}

impl AuthConfig {
    pub fn new(secret: &str) -> Self {
        AuthConfig {
            secret: secret.to_string(),
            token_ttl_secs: 3600, // 1시간
            public_paths: vec![
                "/health".into(),
                "/routes".into(),
                "/".into(),
                "/auth/status".into(),
            ],
            readonly_paths: vec![
                "/emit".into(),
                "/lifecycle".into(),
                "/deficiencies".into(),
                "/reload/status".into(),
                "/federation".into(),
                "/mutations".into(),
                "/snapshot".into(),
                "/views".into(),
            ],
        }
    }

    pub fn with_ttl(mut self, secs: u64) -> Self {
        self.token_ttl_secs = secs;
        self
    }

    pub fn add_public_path(mut self, path: &str) -> Self {
        self.public_paths.push(path.to_string());
        self
    }

    /// 경로가 공개인지 확인
    pub fn is_public(&self, path: &str) -> bool {
        self.public_paths.iter().any(|p| {
            if p == "/" { path == "/" } else { path == p || path.starts_with(p.as_str()) }
        })
    }

    /// 경로가 읽기 전용으로 접근 가능한지
    pub fn is_readonly_path(&self, path: &str) -> bool {
        self.readonly_paths.iter().any(|p| path == p || path.starts_with(p.as_str()))
    }

    /// 경로 접근에 필요한 최소 권한 (None = 공개)
    pub fn required_permission(&self, method: &str, path: &str) -> Option<Permission> {
        // 1. 공개 경로
        if self.is_public(path) {
            return None;
        }
        // 2. Admin 전용
        if path == "/auth/keys" {
            return Some(Permission::Admin);
        }
        // 3. GET + 읽기 전용 경로
        if method == "GET" && self.is_readonly_path(path) {
            return Some(Permission::ReadOnly);
        }
        // 4. 쓰기 작업 (POST/PUT/DELETE)
        if matches!(method, "POST" | "PUT" | "DELETE") {
            return Some(Permission::ReadWrite);
        }
        // 5. 나머지 GET
        Some(Permission::ReadOnly)
    }
}

impl Default for AuthConfig {
    fn default() -> Self {
        Self::new("world-engine-default-secret-change-me")
    }
}

// ============================================================
// AuthResult - 인증 결과
// ============================================================

#[derive(Debug, Clone, PartialEq)]
pub enum AuthResult {
    /// 인증 성공 (권한 포함)
    Allowed(Permission),
    /// 공개 경로 (인증 불필요)
    Public,
    /// 인증 실패 (이유)
    Denied(String),
}

impl AuthResult {
    pub fn is_ok(&self) -> bool {
        matches!(self, AuthResult::Allowed(_) | AuthResult::Public)
    }

    pub fn permission(&self) -> Option<&Permission> {
        if let AuthResult::Allowed(p) = self { Some(p) } else { None }
    }

    pub fn to_json_error(&self) -> serde_json::Value {
        match self {
            AuthResult::Denied(msg) => serde_json::json!({ "error": msg }),
            _ => serde_json::json!({ "error": "unauthorized" }),
        }
    }
}

// ============================================================
// AuthMiddleware - 헤더 파싱 + 검증
// ============================================================

pub struct AuthMiddleware;

impl AuthMiddleware {
    /// 요청 헤더에서 인증 정보 추출/검증
    pub fn authenticate(manager: &AuthManager, headers: &HashMap<String, String>) -> AuthResult {
        // 1. X-Api-Key 헤더 확인
        if let Some(key_raw) = headers.get("x-api-key").or_else(|| headers.get("X-Api-Key")) {
            return Self::check_api_key(manager, key_raw);
        }

        // 2. Authorization: Bearer <token>
        if let Some(auth_hdr) = headers.get("authorization").or_else(|| headers.get("Authorization")) {
            if let Some(token) = auth_hdr.strip_prefix("Bearer ").or_else(|| auth_hdr.strip_prefix("bearer ")) {
                return Self::check_token(manager, token);
            }
        }

        AuthResult::Denied("인증 정보 없음 (X-Api-Key 또는 Authorization: Bearer <token>)".into())
    }

    fn check_api_key(manager: &AuthManager, raw: &str) -> AuthResult {
        let perm = manager.key_store.lock().unwrap().verify(raw);
        match perm {
            Some(p) => AuthResult::Allowed(p),
            None    => AuthResult::Denied(format!("유효하지 않은 API Key: {}", &raw[..raw.len().min(8)])),
        }
    }

    fn check_token(manager: &AuthManager, raw: &str) -> AuthResult {
        match manager.verify_token(raw) {
            Ok(claims) => AuthResult::Allowed(claims.permission),
            Err(e)     => AuthResult::Denied(format!("토큰 오류: {}", e)),
        }
    }

    /// 경로 + 메서드에 대한 권한 검사
    pub fn authorize(
        auth_result: &AuthResult,
        required: Option<Permission>,
    ) -> bool {
        match required {
            None => true, // 공개 경로
            Some(req) => match auth_result {
                AuthResult::Public => true,
                AuthResult::Allowed(p) => *p >= req,
                AuthResult::Denied(_) => false,
            },
        }
    }
}

// ============================================================
// HTTP 헤더 파싱 헬퍼
// ============================================================

pub fn parse_headers(raw_lines: &[String]) -> HashMap<String, String> {
    let mut map = HashMap::new();
    for line in raw_lines {
        if let Some((k, v)) = line.split_once(':') {
            map.insert(k.trim().to_lowercase(), v.trim().to_string());
        }
    }
    map
}

