static EVENT_COUNTER: std::sync::atomic::AtomicU64
    = std::sync::atomic::AtomicU64::new(1);

fn next_event_id() -> u64 {
    EVENT_COUNTER.fetch_add(1, std::sync::atomic::Ordering::SeqCst)
}

fn unix_now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

