use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

// ─── 이벤트 타입 ─────────────────────────────────────────

#[derive(Debug, Clone, PartialEq)]
pub enum EventKind {
    Insert,
    Update,
    Delete,
    SchemaChange,
    Custom(String),
}

impl EventKind {
    pub fn as_str(&self) -> &str {
        match self {
            EventKind::Insert       => "insert",
            EventKind::Update       => "update",
            EventKind::Delete       => "delete",
            EventKind::SchemaChange => "schema_change",
            EventKind::Custom(s)    => s.as_str(),
        }
    }

    pub fn from_str(s: &str) -> Self {
        match s {
            "insert"        => EventKind::Insert,
            "update"        => EventKind::Update,
            "delete"        => EventKind::Delete,
            "schema_change" => EventKind::SchemaChange,
            other           => EventKind::Custom(other.to_string()),
        }
    }
}

// ─── DbEvent ─────────────────────────────────────────────

#[derive(Debug, Clone)]
pub struct DbEvent {
    pub id:         u64,
    pub kind:       EventKind,
    pub intent:     String,
    pub table:      String,
    pub row_id:     Option<String>,
    pub payload:    serde_json::Value,
    pub timestamp:  u64,
}

impl DbEvent {
    pub fn new(
        kind: EventKind,
        intent: &str,
        table: &str,
        row_id: Option<&str>,
        payload: serde_json::Value,
    ) -> Self {
        DbEvent {
            id:        next_event_id(),
            kind,
            intent:    intent.to_string(),
            table:     table.to_string(),
            row_id:    row_id.map(|s| s.to_string()),
            payload,
            timestamp: unix_now(),
        }
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "id":        self.id,
            "kind":      self.kind.as_str(),
            "intent":    self.intent,
            "table":     self.table,
            "row_id":    self.row_id,
            "payload":   self.payload,
            "timestamp": self.timestamp,
        })
    }

    /// SSE 형식: "data: <json>\n\n"
    pub fn to_sse(&self) -> String {
        format!("id: {}\nevent: {}\ndata: {}\n\n",
            self.id,
            self.kind.as_str(),
            self.to_json(),
        )
    }
}

// ─── 구독 필터 ────────────────────────────────────────────

#[derive(Debug, Clone)]
pub struct EventFilter {
    /// None = 모든 intent
    pub intent: Option<String>,
    /// None = 모든 이벤트 종류
    pub kinds: Option<Vec<EventKind>>,
}

impl EventFilter {
    pub fn all() -> Self {
        EventFilter { intent: None, kinds: None }
    }

    pub fn for_intent(intent: &str) -> Self {
        EventFilter { intent: Some(intent.to_string()), kinds: None }
    }

    pub fn matches(&self, event: &DbEvent) -> bool {
        if let Some(ref i) = self.intent {
            if &event.intent != i {
                return false;
            }
        }
        if let Some(ref kinds) = self.kinds {
            if !kinds.contains(&event.kind) {
                return false;
            }
        }
        true
    }

    pub fn from_json(json: &serde_json::Value) -> Self {
        let intent = json["intent"].as_str().map(|s| s.to_string());
        let kinds = json["kinds"].as_array().map(|arr| {
            arr.iter()
               .filter_map(|v| v.as_str())
               .map(EventKind::from_str)
               .collect()
        });
        EventFilter { intent, kinds }
    }
}

