use std::sync::Arc;
use std::collections::HashMap;
use world_engine::events::{
    DbEvent, EventBus, EventFilter, EventKind,
    new_event_bus, SharedEventBus,
};
use world_engine::auth::{AuthManager, middleware::AuthConfig};

// ─── EventKind ────────────────────────────────────────────

#[test]
fn test_event_kind_as_str() {
    assert_eq!(EventKind::Insert.as_str(), "insert");
    assert_eq!(EventKind::Update.as_str(), "update");
    assert_eq!(EventKind::Delete.as_str(), "delete");
    assert_eq!(EventKind::SchemaChange.as_str(), "schema_change");
    assert_eq!(EventKind::Custom("ping".into()).as_str(), "ping");
}

#[test]
fn test_event_kind_from_str() {
    assert_eq!(EventKind::from_str("insert"),        EventKind::Insert);
    assert_eq!(EventKind::from_str("update"),        EventKind::Update);
    assert_eq!(EventKind::from_str("delete"),        EventKind::Delete);
    assert_eq!(EventKind::from_str("schema_change"), EventKind::SchemaChange);
    assert_eq!(EventKind::from_str("custom_op"),     EventKind::Custom("custom_op".into()));
}

// ─── DbEvent ─────────────────────────────────────────────

#[test]
fn test_db_event_new() {
    let e = DbEvent::new(
        EventKind::Insert, "Shop", "Product",
        Some("abc-123"),
        serde_json::json!({"name": "Widget"}),
    );
    assert_eq!(e.kind, EventKind::Insert);
    assert_eq!(e.intent, "Shop");
    assert_eq!(e.table, "Product");
    assert_eq!(e.row_id.as_deref(), Some("abc-123"));
    assert!(e.id > 0);
    assert!(e.timestamp > 0);
}

#[test]
fn test_db_event_unique_ids() {
    let e1 = DbEvent::new(EventKind::Insert, "A", "T", None, serde_json::Value::Null);
    let e2 = DbEvent::new(EventKind::Insert, "A", "T", None, serde_json::Value::Null);
    assert_ne!(e1.id, e2.id);
}

#[test]
fn test_db_event_to_json() {
    let e = DbEvent::new(EventKind::Update, "Inv", "Item", Some("x1"), serde_json::json!({}));
    let j = e.to_json();
    assert_eq!(j["kind"].as_str().unwrap(), "update");
    assert_eq!(j["intent"].as_str().unwrap(), "Inv");
    assert_eq!(j["table"].as_str().unwrap(), "Item");
    assert_eq!(j["row_id"].as_str().unwrap(), "x1");
}

#[test]
fn test_db_event_to_sse_format() {
    let e = DbEvent::new(EventKind::Delete, "S", "R", None, serde_json::Value::Null);
    let sse = e.to_sse();
    assert!(sse.starts_with("id: "));
    assert!(sse.contains("event: delete"));
    assert!(sse.contains("data: "));
    assert!(sse.ends_with("\n\n"));
}

// ─── EventFilter ─────────────────────────────────────────

#[test]
fn test_filter_all_matches_everything() {
    let f = EventFilter::all();
    let e = DbEvent::new(EventKind::Insert, "Any", "T", None, serde_json::Value::Null);
    assert!(f.matches(&e));
}

#[test]
fn test_filter_for_intent_matches() {
    let f = EventFilter::for_intent("Shop");
    let yes = DbEvent::new(EventKind::Insert, "Shop", "T", None, serde_json::Value::Null);
    let no  = DbEvent::new(EventKind::Insert, "Inv",  "T", None, serde_json::Value::Null);
    assert!(f.matches(&yes));
    assert!(!f.matches(&no));
}

#[test]
fn test_filter_kinds() {
    let f = EventFilter {
        intent: None,
        kinds: Some(vec![EventKind::Insert, EventKind::Update]),
    };
    let ins = DbEvent::new(EventKind::Insert, "X", "T", None, serde_json::Value::Null);
    let del = DbEvent::new(EventKind::Delete, "X", "T", None, serde_json::Value::Null);
    assert!(f.matches(&ins));
    assert!(!f.matches(&del));
}

#[test]
fn test_filter_from_json() {
    let j = serde_json::json!({ "intent": "Shop", "kinds": ["insert", "update"] });
    let f = EventFilter::from_json(&j);
    assert_eq!(f.intent.as_deref(), Some("Shop"));
    assert!(f.kinds.is_some());
}

// ─── EventBus ────────────────────────────────────────────

#[test]
fn test_publish_and_subscribe() {
    let bus = EventBus::new(10);
    let (_, rx) = bus.subscribe(EventFilter::all());

    bus.publish(DbEvent::new(EventKind::Insert, "S", "T", None, serde_json::Value::Null));

    let received = rx.recv().unwrap();
    assert_eq!(received.kind, EventKind::Insert);
}

#[test]
fn test_subscriber_count() {
    let bus = EventBus::new(10);
    assert_eq!(bus.subscriber_count(), 0);
    let (id, _rx) = bus.subscribe(EventFilter::all());
    assert_eq!(bus.subscriber_count(), 1);
    bus.unsubscribe(id);
    // 구독 해제 후 카운트
    assert_eq!(bus.subscriber_count(), 0);
}

#[test]
fn test_filter_by_intent_on_bus() {
    let bus = EventBus::new(10);
    let (_, rx_shop) = bus.subscribe(EventFilter::for_intent("Shop"));
    let (_, rx_all)  = bus.subscribe(EventFilter::all());

    bus.publish(DbEvent::new(EventKind::Insert, "Inv", "T", None, serde_json::Value::Null));
    bus.publish(DbEvent::new(EventKind::Insert, "Shop", "T", None, serde_json::Value::Null));

    // Shop 구독자는 Shop 이벤트만
    let e = rx_shop.recv().unwrap();
    assert_eq!(e.intent, "Shop");
