#[test]
fn test_render_dashboard_returns_html() {
    let graph = make_graph();
    let metrics = DashboardMetrics {
        intent_count: 2, schema_count: 2, action_count: 3, route_count: 5,
        record_counts: vec![], auth_enabled: false, rl_enabled: false,
