#[test]
fn test_router_dashboard_endpoint() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = make_graph();
    let result = Synthesizer::synthesize(&graph);
    let mut router = Router::from_graph(graph);
    let (status, json) = router.handle(&mut { result.db }, "GET", "/dashboard", "");
    assert_eq!(status, 200);
    // HTML 응답은 __html__ 키에 담아 반환
    let html = json["__html__"].as_str().unwrap();
    assert!(html.contains("<!DOCTYPE html>"));
    assert!(html.contains("World Engine"));
}

#[test]
fn test_router_dashboard_metrics_endpoint() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = make_graph();
    let result = Synthesizer::synthesize(&graph);
    let mut router = Router::from_graph(graph);
    let (status, json) = router.handle(&mut { result.db }, "GET", "/dashboard/metrics", "");
    assert_eq!(status, 200);
    assert!(json["intents"].as_u64().is_some());
    assert!(json["schemas"].as_u64().is_some());
    assert!(json["routes"].as_u64().is_some());
    assert!(json["uptime_secs"].as_u64().is_some());
}

#[test]
fn test_router_metrics_correct_counts() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = make_graph(); // Shop(1 schema, 2 action) + Order(1 schema, 1 action)
    let result = Synthesizer::synthesize(&graph);
    let mut router = Router::from_graph(graph);
    let (_, json) = router.handle(&mut { result.db }, "GET", "/dashboard/metrics", "");
    assert_eq!(json["intents"].as_u64().unwrap(), 2);
    assert_eq!(json["schemas"].as_u64().unwrap(), 2);
    assert_eq!(json["actions"].as_u64().unwrap(), 3);
}

#[test]
fn test_router_metrics_auth_enabled_flag() {
    use std::sync::Arc;
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    use world_engine::auth::{AuthManager, middleware::AuthConfig};
    let graph = make_graph();
    let result = Synthesizer::synthesize(&graph);
    let am = Arc::new(AuthManager::new(AuthConfig::new("secret")));
    let mut router = Router::from_graph(graph).with_auth(Arc::clone(&am));
    let (_, json) = router.handle(&mut { result.db }, "GET", "/dashboard/metrics", "");
    assert_eq!(json["auth_enabled"].as_bool().unwrap(), true);
    assert_eq!(json["rl_enabled"].as_bool().unwrap(), false);
}

