// ============================================================
// Dashboard HTML 생성기
// ============================================================
// GET /dashboard → 전체 상태를 보여주는 HTML 페이지 (인라인 CSS/JS)
// GET /dashboard/metrics → JSON 메트릭
// 외부 crate 없이 순수 Rust std
// ============================================================

use crate::ast::{IntentGraph, Annotation};
use crate::synthesizer::kimdb::KimDB;

// ─── DashboardMetrics ─────────────────────────────────────

#[derive(Debug, Clone)]
pub struct DashboardMetrics {
    pub intent_count:  usize,
    pub schema_count:  usize,
    pub action_count:  usize,
    pub route_count:   usize,
    pub record_counts: Vec<(String, usize)>, // (table_name, count)
    pub auth_enabled:  bool,
    pub rl_enabled:    bool,
    pub events_enabled: bool,
    pub uptime_secs:   u64,
}

impl DashboardMetrics {
    pub fn to_json(&self) -> serde_json::Value {
        let tables: serde_json::Value = self.record_counts.iter()
            .map(|(t, c)| serde_json::json!({ "table": t, "count": c }))
            .collect::<Vec<_>>()
            .into();
        serde_json::json!({
            "intents":        self.intent_count,
            "schemas":        self.schema_count,
            "actions":        self.action_count,
            "routes":         self.route_count,
            "auth_enabled":   self.auth_enabled,
            "rl_enabled":     self.rl_enabled,
            "events_enabled": self.events_enabled,
            "uptime_secs":    self.uptime_secs,
            "tables":         tables,
        })
    }
}

// ─── HTML 생성 ────────────────────────────────────────────

pub fn render_dashboard(
    graph: &IntentGraph,
    metrics: &DashboardMetrics,
    version: &str,
) -> String {
    let intent_rows = graph.intents.iter().map(|intent| {
        let schemas = intent.schemas.iter()
            .map(|s| {
                let fields = s.fields.iter()
                    .map(|f| {
                        let is_pk  = f.annotations.iter().any(|a| matches!(a, Annotation::Primary));
                        let is_req = f.annotations.iter().any(|a| matches!(a, Annotation::Required));
                        format!(
                            "<span class='field'>{}: <em>{}</em>{}</span>",
                            f.name,
                            f.field_type,
                            if is_pk { " <sup>PK</sup>" }
                            else if is_req { " <sup>*</sup>" }
                            else { "" }
                        )
                    })
                    .collect::<Vec<_>>()
                    .join(", ");

                // record count
                let count = metrics.record_counts.iter()
                    .find(|(t, _)| t == &format!("{}.{}", intent.name, s.name))
                    .map(|(_, c)| *c)
                    .unwrap_or(0);

                format!(
                    "<div class='schema'><strong>{}</strong> \
                     <span class='badge'>{} rows</span><br><span class='fields'>{}</span></div>",
                    s.name, count, fields
                )
            })
            .collect::<Vec<_>>()
            .join("");

        let actions = intent.actions.iter()
            .map(|a| format!("<span class='action'>{}()</span>", a.name))
            .collect::<Vec<_>>()
            .join(" ");

        format!(
            "<tr><td><strong>{}</strong></td><td>{}</td><td class='actions'>{}</td></tr>",
            intent.name, schemas, actions
        )
    }).collect::<Vec<_>>().join("\n");

    let status_badges = format!(
        "{} {} {}",
        badge("Auth",   metrics.auth_enabled,   "green", "gray"),
        badge("RateLimit", metrics.rl_enabled,  "green", "gray"),
        badge("Events", metrics.events_enabled, "green", "gray"),
    );

    format!(r#"<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>World Engine Dashboard</title>
<style>
  :root {{
    --bg: #0f1117; --surface: #1a1d27; --border: #2d3048;
    --text: #e2e8f0; --muted: #64748b; --accent: #6366f1;
    --green: #22c55e; --yellow: #eab308; --red: #ef4444;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{ background: var(--bg); color: var(--text); font-family: 'Segoe UI', sans-serif; padding: 1.5rem; }}
  h1 {{ font-size: 1.6rem; color: var(--accent); margin-bottom: .25rem; }}
  .subtitle {{ color: var(--muted); font-size: .85rem; margin-bottom: 1.5rem; }}
  .cards {{ display: flex; gap: 1rem; flex-wrap: wrap; margin-bottom: 1.5rem; }}
  .card {{ background: var(--surface); border: 1px solid var(--border); border-radius: .75rem;
           padding: 1rem 1.5rem; min-width: 120px; text-align: center; }}
  .card .num {{ font-size: 2rem; font-weight: 700; color: var(--accent); }}
  .card .label {{ font-size: .75rem; color: var(--muted); margin-top: .25rem; }}
  .status-row {{ margin-bottom: 1.5rem; display: flex; gap: .5rem; align-items: center; flex-wrap: wrap; }}
  .badge {{ padding: .2rem .6rem; border-radius: 999px; font-size: .75rem; font-weight: 600; }}
  .badge.on  {{ background: #14532d; color: #86efac; }}
  .badge.off {{ background: #1f2937; color: #6b7280; }}
  table {{ width: 100%; border-collapse: collapse; background: var(--surface);
           border: 1px solid var(--border); border-radius: .75rem; overflow: hidden; }}
  th {{ background: var(--border); padding: .75rem 1rem; text-align: left;
        font-size: .8rem; color: var(--muted); text-transform: uppercase; }}
  td {{ padding: .75rem 1rem; border-top: 1px solid var(--border); vertical-align: top; }}
  .schema {{ margin-bottom: .5rem; }}
  .fields {{ color: var(--muted); font-size: .8rem; }}
  .field {{ margin-right: .5rem; }}
  em {{ color: #93c5fd; font-style: normal; }}
  sup {{ color: var(--yellow); font-size: .65rem; }}
  .actions {{ color: #a78bfa; font-size: .85rem; }}
  .action {{ margin-right: .4rem; }}
  footer {{ margin-top: 2rem; color: var(--muted); font-size: .75rem; text-align: center; }}
  .refresh-btn {{ background: var(--accent); color: #fff; border: none; padding: .4rem .9rem;
                  border-radius: .4rem; cursor: pointer; font-size: .8rem; margin-left: auto; }}
</style>
</head>
<body>
<div style="display:flex;align-items:baseline;gap:1rem;margin-bottom:.25rem">
  <h1>⚡ World Engine</h1>
  <span style="color:var(--muted);font-size:.8rem">v{version}</span>
  <button class="refresh-btn" onclick="location.reload()">새로고침</button>
</div>
<p class="subtitle">Intent-Driven Computing Dashboard · uptime {uptime}s</p>

<div class="cards">
  <div class="card"><div class="num">{intents}</div><div class="label">Intents</div></div>
  <div class="card"><div class="num">{schemas}</div><div class="label">Schemas</div></div>
  <div class="card"><div class="num">{actions}</div><div class="label">Actions</div></div>
  <div class="card"><div class="num">{routes}</div><div class="label">Routes</div></div>
</div>

<div class="status-row">
  <span style="color:var(--muted);font-size:.8rem">기능:</span>
  {status}
</div>

<table>
  <thead>
    <tr>
      <th>Intent</th>
      <th>Schemas & Fields</th>
      <th>Actions</th>
    </tr>
  </thead>
  <tbody>
    {rows}
  </tbody>
</table>

<footer>World Engine Dashboard · <a href="/routes" style="color:var(--accent)">Routes</a> ·
<a href="/health" style="color:var(--accent)">Health</a> ·
<a href="/dashboard/metrics" style="color:var(--accent)">JSON Metrics</a></footer>

<script>
  // 30초 자동 갱신
  setTimeout(() => location.reload(), 30000);
</script>
</body>
</html>"#,
        version  = version,
        uptime   = metrics.uptime_secs,
        intents  = metrics.intent_count,
        schemas  = metrics.schema_count,
        actions  = metrics.action_count,
        routes   = metrics.route_count,
        status   = status_badges,
        rows     = intent_rows,
    )
}

fn badge(label: &str, on: bool, _on_color: &str, _off_color: &str) -> String {
    let cls = if on { "on" } else { "off" };
    let icon = if on { "✓" } else { "–" };
    format!("<span class='badge {}'>{} {}</span>", cls, icon, label)
}

// ─── KimDB 레코드 수 수집 ─────────────────────────────────

pub fn collect_record_counts(graph: &IntentGraph, db: &KimDB) -> Vec<(String, usize)> {
    let mut result = Vec::new();
    for intent in &graph.intents {
        for schema in &intent.schemas {
            let table_key = format!("{}.{}", intent.name, schema.name);
            let table_name = format!("{}.{}", intent.name, schema.name);
            let count = db.select_all(&table_name)
                .map(|rows| rows.len())
                .unwrap_or(0);
            result.push((table_key, count));
        }
    }
    result
}

use std::collections::{HashMap, HashSet};
use crate::auth::apikey::Permission;
use crate::auth::AuthManager;

// ============================================================
// AuthConfig - 인증 설정
// ============================================================

#[derive(Debug, Clone)]
pub struct AuthConfig {
    pub secret: String,
    pub token_ttl_secs: u64,
    /// 인증 없이 접근 가능한 경로 접두사
    pub public_paths: Vec<String>,
    /// 읽기 전용 경로 (ReadOnly 권한으로 충분)
    pub readonly_paths: Vec<String>,
}

impl AuthConfig {
    pub fn new(secret: &str) -> Self {
        AuthConfig {
            secret: secret.to_string(),
            token_ttl_secs: 3600, // 1시간
            public_paths: vec![
                "/health".into(),
                "/routes".into(),
                "/".into(),
                "/auth/status".into(),
                "/auth/ratelimit".into(),
            ],
            readonly_paths: vec![
                "/emit".into(),
                "/lifecycle".into(),
                "/deficiencies".into(),
                "/reload/status".into(),
                "/federation".into(),
                "/mutations".into(),
                "/snapshot".into(),
                "/views".into(),
            ],
        }
    }

    pub fn with_ttl(mut self, secs: u64) -> Self {
        self.token_ttl_secs = secs;
        self
    }

    pub fn add_public_path(mut self, path: &str) -> Self {
        self.public_paths.push(path.to_string());
        self
    }

    /// 경로가 공개인지 확인
    pub fn is_public(&self, path: &str) -> bool {
        self.public_paths.iter().any(|p| {
            if p == "/" { path == "/" } else { path == p || path.starts_with(p.as_str()) }
        })
    }

    /// 경로가 읽기 전용으로 접근 가능한지
    pub fn is_readonly_path(&self, path: &str) -> bool {
        self.readonly_paths.iter().any(|p| path == p || path.starts_with(p.as_str()))
    }

    /// 경로 접근에 필요한 최소 권한 (None = 공개)
    pub fn required_permission(&self, method: &str, path: &str) -> Option<Permission> {
        // 1. 공개 경로
        if self.is_public(path) {
            return None;
        }
        // 2. Admin 전용
        if path == "/auth/keys" {
            return Some(Permission::Admin);
        }
        // 3. GET + 읽기 전용 경로
        if method == "GET" && self.is_readonly_path(path) {
            return Some(Permission::ReadOnly);
        }
        // 4. 쓰기 작업 (POST/PUT/DELETE)
        if matches!(method, "POST" | "PUT" | "DELETE") {
            return Some(Permission::ReadWrite);
        }
        // 5. 나머지 GET
        Some(Permission::ReadOnly)
    }
}

impl Default for AuthConfig {
    fn default() -> Self {
        Self::new("world-engine-default-secret-change-me")
    }
}

// ============================================================
// AuthResult - 인증 결과
// ============================================================

#[derive(Debug, Clone, PartialEq)]
pub enum AuthResult {
    /// 인증 성공 (권한 포함)
    Allowed(Permission),
    /// 공개 경로 (인증 불필요)
    Public,
    /// 인증 실패 (이유)
    Denied(String),
}

impl AuthResult {
    pub fn is_ok(&self) -> bool {
        matches!(self, AuthResult::Allowed(_) | AuthResult::Public)
    }

    pub fn permission(&self) -> Option<&Permission> {
        if let AuthResult::Allowed(p) = self { Some(p) } else { None }
    }

    pub fn to_json_error(&self) -> serde_json::Value {
        match self {
            AuthResult::Denied(msg) => serde_json::json!({ "error": msg }),
            _ => serde_json::json!({ "error": "unauthorized" }),
        }
    }
}

// ============================================================
// AuthMiddleware - 헤더 파싱 + 검증
// ============================================================

pub struct AuthMiddleware;

impl AuthMiddleware {
    /// 요청 헤더에서 인증 정보 추출/검증
    pub fn authenticate(manager: &AuthManager, headers: &HashMap<String, String>) -> AuthResult {
        // 1. X-Api-Key 헤더 확인
        if let Some(key_raw) = headers.get("x-api-key").or_else(|| headers.get("X-Api-Key")) {
            return Self::check_api_key(manager, key_raw);
        }

        // 2. Authorization: Bearer <token>
        if let Some(auth_hdr) = headers.get("authorization").or_else(|| headers.get("Authorization")) {
            if let Some(token) = auth_hdr.strip_prefix("Bearer ").or_else(|| auth_hdr.strip_prefix("bearer ")) {
                return Self::check_token(manager, token);
            }
        }

        AuthResult::Denied("인증 정보 없음 (X-Api-Key 또는 Authorization: Bearer <token>)".into())
    }

    fn check_api_key(manager: &AuthManager, raw: &str) -> AuthResult {
        let perm = manager.key_store.lock().unwrap().verify(raw);
        match perm {
            Some(p) => AuthResult::Allowed(p),
            None    => AuthResult::Denied(format!("유효하지 않은 API Key: {}", &raw[..raw.len().min(8)])),
        }
    }

    fn check_token(manager: &AuthManager, raw: &str) -> AuthResult {
        match manager.verify_token(raw) {
            Ok(claims) => AuthResult::Allowed(claims.permission),
            Err(e)     => AuthResult::Denied(format!("토큰 오류: {}", e)),
        }
    }

    /// 경로 + 메서드에 대한 권한 검사
    pub fn authorize(
        auth_result: &AuthResult,
        required: Option<Permission>,
    ) -> bool {
        match required {
            None => true, // 공개 경로
            Some(req) => match auth_result {
                AuthResult::Public => true,
                AuthResult::Allowed(p) => *p >= req,
                AuthResult::Denied(_) => false,
            },
        }
    }
}

// ============================================================
// HTTP 헤더 파싱 헬퍼
// ============================================================

pub fn parse_headers(raw_lines: &[String]) -> HashMap<String, String> {
    let mut map = HashMap::new();
    for line in raw_lines {
        if let Some((k, v)) = line.split_once(':') {
            map.insert(k.trim().to_lowercase(), v.trim().to_string());
        }
    }
    map
}

