// ─── 시나리오 2: 인증 + Rate Limiting 통합 흐름 ──────────

#[test]
fn e2e_auth_ratelimit_flow() {
    let graph = parse(r#"
intent Warehouse {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Item { id: uuid @primary, name: string @required, }
    action list() { return 0; }
}
"#).unwrap();
    let result = Synthesizer::synthesize(&graph);
    let mut db = result.db;

    // Auth + Rate Limit 설정 (ReadWrite: 3회/윈도우)
    let am = Arc::new(
        AuthManager::new(AuthConfig::new("e2e-secret"))
            .with_rate_limit(RateLimitConfig::new(60, 5, 3, 100))
    );
    let admin_key = am.issue_api_key("admin", Permission::Admin);
    let rw_key    = am.issue_api_key("writer", Permission::ReadWrite);

    let mut router = Router::from_graph(graph).with_auth(Arc::clone(&am));

    // 1. 인증 없이 보호된 경로 → 401
    let (s, _) = router.handle(&mut db, "POST", "/Warehouse/list", "{}");
    assert_eq!(s, 401, "인증 없이 접근 가능");

    // 2. 유효한 키로 접근 성공
    let h = hdrs(&[("x-api-key", &rw_key)]);
    let (s, _) = router.handle_with_headers(&mut db, "POST", "/Warehouse/list", "{}", &h);
    assert_eq!(s, 200, "유효한 키 거부됨");

    // 3. Rate Limit 도달
    for i in 0..2 {
        let (s, _) = router.handle_with_headers(&mut db, "POST", "/Warehouse/list", "{}", &h);
        assert_ne!(s, 429, "{}번째 요청이 미리 차단됨", i + 2);
    }
    let (s, j) = router.handle_with_headers(&mut db, "POST", "/Warehouse/list", "{}", &h);
    assert_eq!(s, 429, "Rate Limit 미작동");
    assert!(j["reset_secs"].as_u64().is_some());

    // 4. Admin 키로 API Key 발급
    let ah = hdrs(&[("x-api-key", &admin_key)]);
    let (s, j) = router.handle_with_headers(
        &mut db, "POST", "/auth/keys",
        r#"{"label":"ci","permission":"readonly"}"#, &ah
    );
    assert_eq!(s, 200);
    assert!(j["key"].as_str().unwrap().starts_with("we_"));

    // 5. Token 발급 & Bearer 인증
    let (s, j) = router.handle_with_headers(
        &mut db, "POST", "/auth/token",
        r#"{"subject":"ci"}"#, &ah
    );
    assert_eq!(s, 200);
    let token = j["token"].as_str().unwrap().to_string();
    assert!(token.contains('.'));

    let th = hdrs(&[("authorization", &format!("Bearer {}", token))]);
    let (s, _) = router.handle_with_headers(&mut db, "GET", "/Warehouse/Item", "", &th);
    assert_eq!(s, 200, "Bearer 토큰 인증 실패");
}

