#[test]
fn e2e_shop_full_pipeline() {
    // 1. FL 소스 파싱
    let graph = parse(r#"
intent Shop {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Product {
        id:    uuid   @primary,
        name:  string @required,
        stock: u32    @default(0),
    }
    action restock(qty: u32) { return 0; }
    action sell(qty: u32)    { return 0; }
    view ProductGrid { source: Product, render: grid, }
}
"#).expect("FL 파싱 실패");

    // 2. 신디사이즈
    let result = Synthesizer::synthesize(&graph);
    let mut db = result.db;

    // 3. Router 생성
    let mut router = Router::from_graph(graph);

    // 4. Health check
    let (s, j) = router.handle(&mut db, "GET", "/health", "");
    assert_eq!(s, 200, "health 실패");
    assert_eq!(j["status"].as_str().unwrap(), "ok");

    // 5. 라우트 목록 확인
    let (s, j) = router.handle(&mut db, "GET", "/routes", "");
    assert_eq!(s, 200);
    assert!(j["count"].as_u64().unwrap() > 0);

    // 6. 상품 조회 (빈 상태)
    let (s, j) = router.handle(&mut db, "GET", "/Shop/Product", "");
    assert_eq!(s, 200);
    assert_eq!(j["rows"].as_array().unwrap().len(), 0);

    // 7. 재입고 액션
    let (s, j) = router.handle(&mut db, "POST", "/Shop/restock",
        r#"{"qty": 100}"#);
    assert_eq!(s, 200, "restock 실패: {:?}", j);

    // 8. 상품 목록 재확인
    let (s, j) = router.handle(&mut db, "GET", "/Shop/Product", "");
    assert_eq!(s, 200);

    // 9. 뷰 렌더링
    let (s, j) = router.handle(&mut db, "GET", "/views", "");
    assert_eq!(s, 200);
    assert!(j["count"].as_u64().unwrap() > 0);

    // 10. 결핍 검사
    let (s, j) = router.handle(&mut db, "GET", "/deficiencies", "");
    assert_eq!(s, 200);
    assert!(j["healthy"].as_bool().is_some());
}

// ─── 시나리오 2: 인증 + Rate Limiting 통합 흐름 ──────────

#[test]
fn e2e_auth_ratelimit_flow() {
    let graph = parse(r#"
intent Warehouse {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Item { id: uuid @primary, name: string @required, }
    action list() { return 0; }
}
"#).unwrap();
    let result = Synthesizer::synthesize(&graph);
    let mut db = result.db;

    // Auth + Rate Limit 설정 (ReadWrite: 3회/윈도우)
    let am = Arc::new(
        AuthManager::new(AuthConfig::new("e2e-secret"))
            .with_rate_limit(RateLimitConfig::new(60, 5, 3, 100))
    );
    let admin_key = am.issue_api_key("admin", Permission::Admin);
    let rw_key    = am.issue_api_key("writer", Permission::ReadWrite);

    let mut router = Router::from_graph(graph).with_auth(Arc::clone(&am));

    // 1. 인증 없이 보호된 경로 → 401
    let (s, _) = router.handle(&mut db, "POST", "/Warehouse/list", "{}");
    assert_eq!(s, 401, "인증 없이 접근 가능");

    // 2. 유효한 키로 접근 성공
    let h = hdrs(&[("x-api-key", &rw_key)]);
    let (s, _) = router.handle_with_headers(&mut db, "POST", "/Warehouse/list", "{}", &h);
    assert_eq!(s, 200, "유효한 키 거부됨");

    // 3. Rate Limit 도달
    for i in 0..2 {
        let (s, _) = router.handle_with_headers(&mut db, "POST", "/Warehouse/list", "{}", &h);
        assert_ne!(s, 429, "{}번째 요청이 미리 차단됨", i + 2);
    }
    let (s, j) = router.handle_with_headers(&mut db, "POST", "/Warehouse/list", "{}", &h);
    assert_eq!(s, 429, "Rate Limit 미작동");
    assert!(j["reset_secs"].as_u64().is_some());

    // 4. Admin 키로 API Key 발급
    let ah = hdrs(&[("x-api-key", &admin_key)]);
    let (s, j) = router.handle_with_headers(
        &mut db, "POST", "/auth/keys",
        r#"{"label":"ci","permission":"readonly"}"#, &ah
    );
    assert_eq!(s, 200);
    assert!(j["key"].as_str().unwrap().starts_with("we_"));

    // 5. Token 발급 & Bearer 인증
    let (s, j) = router.handle_with_headers(
        &mut db, "POST", "/auth/token",
        r#"{"subject":"ci"}"#, &ah
    );
    assert_eq!(s, 200);
    let token = j["token"].as_str().unwrap().to_string();
    assert!(token.contains('.'));

    let th = hdrs(&[("authorization", &format!("Bearer {}", token))]);
    let (s, _) = router.handle_with_headers(&mut db, "GET", "/Warehouse/Item", "", &th);
    assert_eq!(s, 200, "Bearer 토큰 인증 실패");
}

// ─── 시나리오 3: 스키마 진화 (Mutation + Migration) ──────

#[test]
fn e2e_schema_evolution() {
    let graph = parse(r#"
intent Blog {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Post { id: uuid @primary, title: string @required, }
    action publish() { return 0; }
}
"#).unwrap();
    let result = Synthesizer::synthesize(&graph);
    let mut db = result.db;
    let mut router = Router::from_graph(graph);

    // 1. 초기 스키마 확인
    let (s, j) = router.handle(&mut db, "GET", "/routes", "");
    assert_eq!(s, 200);
    let initial_routes = j["count"].as_u64().unwrap();

    // 2. Mutation으로 필드 추가
    let (s, j) = router.handle(&mut db, "POST", "/mutate",
        r#"{"op":"add_field","intent":"Blog","schema":"Post","field_name":"author","field_type":"string"}"#);
    assert_eq!(s, 200, "mutate 실패: {:?}", j);
    assert!(j["ok"].as_bool().unwrap());

    // 3. Migration으로 추가 변경
    let body = serde_json::json!({
        "plan": "blog-v2",
        "steps": [
            {
                "version": 1,
                "description": "Add published_at field",
                "kind": "add_field",
                "payload": {
                    "op": "add_field",
                    "intent": "Blog",
                    "schema": "Post",
                    "field_name": "published_at",
                    "field_type": "string"
                }
            },
            {
                "version": 2,
                "description": "Add tags field",
                "kind": "add_field",
                "payload": {
                    "op": "add_field",
                    "intent": "Blog",
                    "schema": "Post",
                    "field_name": "tags",
                    "field_type": "string"
                }
            }
        ]
    }).to_string();
    let (s, j) = router.handle(&mut db, "POST", "/migrate", &body);
    assert_eq!(s, 200, "migration 실패: {:?}", j);
    assert_eq!(j["applied"].as_u64().unwrap(), 2);
    assert!(j["ok"].as_bool().unwrap());

    // 4. 라우트 수 변화 없음 (필드 추가는 라우트 변경 없음)
    let (s, j) = router.handle(&mut db, "GET", "/routes", "");
    assert_eq!(s, 200);
    assert_eq!(j["count"].as_u64().unwrap(), initial_routes);
}

// ─── 시나리오 4: EventBus + Mutation 연계 ─────────────────

#[test]
fn e2e_events_with_mutation() {
    let graph = parse(r#"
intent Inventory {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Stock { id: uuid @primary, item: string @required, qty: u32 @default(0), }
    action restock(qty: u32) { return 0; }
}
"#).unwrap();
    let result = Synthesizer::synthesize(&graph);
    let mut db = result.db;
    let bus = new_event_bus(100);
    let mut router = Router::from_graph(graph)
        .with_event_bus(Arc::clone(&bus));

    // 1. 초기 이벤트 없음
    let (s, j) = router.handle(&mut db, "GET", "/events", "");
    assert_eq!(s, 200);
    assert_eq!(j["events"].as_array().unwrap().len(), 0);

    // 2. Mutation → schema_change 이벤트 자동 발행
    router.handle(&mut db, "POST", "/mutate",
        r#"{"op":"add_field","intent":"Inventory","schema":"Stock","field_name":"location","field_type":"string"}"#);

    // 3. 이벤트 폴링
    let (s, j) = router.handle(&mut db, "GET", "/events", "");
    assert_eq!(s, 200);
    let events = j["events"].as_array().unwrap();
    assert!(!events.is_empty(), "Mutation 후 이벤트 없음");
    assert_eq!(events[0]["kind"].as_str().unwrap(), "schema_change");
    assert_eq!(events[0]["intent"].as_str().unwrap(), "Inventory");

    // 4. 커스텀 이벤트 발행
    router.handle(&mut db, "POST", "/events/publish",
        r#"{"kind":"insert","intent":"Inventory","table":"Stock","payload":{"item":"bolt","qty":500}}"#);

    // 5. last_id로 증분 폴링
    let first_id = events[0]["id"].as_u64().unwrap();
    let path = format!("/events?last_id={}", first_id);
    let (s, j) = router.handle(&mut db, "GET", &path, "");
    assert_eq!(s, 200);
    let new_events = j["events"].as_array().unwrap();
    assert!(!new_events.is_empty());
    assert_eq!(new_events[0]["kind"].as_str().unwrap(), "insert");

    // 6. EventBus 통계
    let (s, j) = router.handle(&mut db, "GET", "/events/stats", "");
    assert_eq!(s, 200);
    assert!(j["buffered_events"].as_u64().unwrap() >= 2);
}

// ─── 시나리오 5: Dashboard 전체 기능 확인 ────────────────

#[test]
fn e2e_dashboard_reflects_system_state() {
    let graph = parse(r#"
intent CRM {
    context { lifecycle: persistent, storage: KimDB.memory_buffer, }
    schema Customer { id: uuid @primary, name: string @required, email: string, }
    schema Contract { id: uuid @primary, value: f64 @required, }
    action onboard() { return 0; }
    view CustomerList { source: Customer, render: list, }
}
"#).unwrap();
    let result = Synthesizer::synthesize(&graph);
    let mut db = result.db;
    let am = Arc::new(AuthManager::new(AuthConfig::new("secret")));
    let bus = new_event_bus(50);
    let mut router = Router::from_graph(graph)
        .with_auth(Arc::clone(&am))
        .with_event_bus(Arc::clone(&bus));

    // 1. JSON 메트릭 검증
    let (s, j) = router.handle(&mut db, "GET", "/dashboard/metrics", "");
    assert_eq!(s, 200);
    assert_eq!(j["intents"].as_u64().unwrap(), 1);
    assert_eq!(j["schemas"].as_u64().unwrap(), 2);
    assert_eq!(j["actions"].as_u64().unwrap(), 1);
    assert_eq!(j["auth_enabled"].as_bool().unwrap(), true);
    assert_eq!(j["events_enabled"].as_bool().unwrap(), true);
    assert_eq!(j["rl_enabled"].as_bool().unwrap(), false);

    // 2. HTML 대시보드 존재 확인
    let (s, j) = router.handle(&mut db, "GET", "/dashboard", "");
