// ============================================================
// Evidence Visualization — 관제 센터 & 타임라인 아카이빙
// ============================================================
// "기록이 증명" — 시스템의 모든 변화를 자동으로 기록하고
// 한눈에 볼 수 있는 HTML 관제 센터를 생성
// ============================================================

use std::collections::HashMap;
use std::sync::Mutex;
use std::time::{SystemTime, UNIX_EPOCH};

// ─── EvidenceKind ────────────────────────────────────────

#[derive(Debug, Clone, PartialEq)]
pub enum EvidenceKind {
    Build,
    TestRun,
    Deployment,
    SchemaMutation,
    Migration,
    EventPublished,
    AuthEvent,
    Custom(String),
}

impl EvidenceKind {
    pub fn as_str(&self) -> &str {
        match self {
            EvidenceKind::Build          => "build",
            EvidenceKind::TestRun        => "test_run",
            EvidenceKind::Deployment     => "deployment",
            EvidenceKind::SchemaMutation => "schema_mutation",
            EvidenceKind::Migration      => "migration",
            EvidenceKind::EventPublished => "event_published",
            EvidenceKind::AuthEvent      => "auth_event",
            EvidenceKind::Custom(s)      => s.as_str(),
        }
    }

    pub fn from_str(s: &str) -> Self {
        match s {
            "build"           => EvidenceKind::Build,
            "test_run"        => EvidenceKind::TestRun,
            "deployment"      => EvidenceKind::Deployment,
            "schema_mutation" => EvidenceKind::SchemaMutation,
            "migration"       => EvidenceKind::Migration,
            "event_published" => EvidenceKind::EventPublished,
            "auth_event"      => EvidenceKind::AuthEvent,
            other             => EvidenceKind::Custom(other.to_string()),
        }
    }

    /// 시각화용 색상 (CSS)
    pub fn color(&self) -> &'static str {
        match self {
            EvidenceKind::Build          => "#22c55e",
            EvidenceKind::TestRun        => "#6366f1",
            EvidenceKind::Deployment     => "#f59e0b",
            EvidenceKind::SchemaMutation => "#ec4899",
            EvidenceKind::Migration      => "#14b8a6",
            EvidenceKind::EventPublished => "#8b5cf6",
            EvidenceKind::AuthEvent      => "#64748b",
            EvidenceKind::Custom(_)      => "#94a3b8",
        }
    }

    pub fn icon(&self) -> &'static str {
        match self {
            EvidenceKind::Build          => "🔨",
            EvidenceKind::TestRun        => "✅",
            EvidenceKind::Deployment     => "🚀",
            EvidenceKind::SchemaMutation => "🔧",
            EvidenceKind::Migration      => "📦",
            EvidenceKind::EventPublished => "📡",
            EvidenceKind::AuthEvent      => "🔑",
            EvidenceKind::Custom(_)      => "📌",
        }
    }
}

// ─── EvidenceRecord ──────────────────────────────────────

#[derive(Debug, Clone)]
pub struct EvidenceRecord {
    pub id:          u64,
    pub kind:        EvidenceKind,
    pub title:       String,
    pub description: String,
    pub metrics:     serde_json::Value,
    pub tags:        Vec<String>,
    pub timestamp:   u64,
    pub success:     bool,
}

impl EvidenceRecord {
    pub fn new(
        kind: EvidenceKind,
        title: &str,
        description: &str,
        metrics: serde_json::Value,
        success: bool,
    ) -> Self {
        EvidenceRecord {
            id:          next_id(),
            kind,
            title:       title.to_string(),
            description: description.to_string(),
            metrics,
            tags:        Vec::new(),
            timestamp:   unix_now(),
            success,
        }
    }

    pub fn with_tag(mut self, tag: &str) -> Self {
        self.tags.push(tag.to_string());
        self
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "id":          self.id,
            "kind":        self.kind.as_str(),
            "title":       self.title,
            "description": self.description,
            "metrics":     self.metrics,
            "tags":        self.tags,
            "timestamp":   self.timestamp,
            "success":     self.success,
            "color":       self.kind.color(),
            "icon":        self.kind.icon(),
        })
    }

    /// 상대 시각 표시 ("3분 전", "2시간 전")
    pub fn relative_time(&self) -> String {
        let now  = unix_now();
        let diff = now.saturating_sub(self.timestamp);
        if diff < 60         { format!("{}초 전", diff) }
        else if diff < 3600  { format!("{}분 전", diff / 60) }
        else if diff < 86400 { format!("{}시간 전", diff / 3600) }
        else                  { format!("{}일 전", diff / 86400) }
    }
}

// ─── InfraMetrics (실시간 인프라 지표) ──────────────────

#[derive(Debug)]
pub struct InfraMetrics {
    pub total_requests:   u64,
    pub success_requests: u64,
    pub error_requests:   u64,
    pub mutation_count:   u64,
    pub migration_count:  u64,
    pub event_count:      u64,
    pub auth_success:     u64,
    pub auth_failure:     u64,
    pub rate_limited:     u64,
    pub last_activity:    u64,
    /// 테이블별 DB 레코드 수 (외부에서 주입)
    pub db_counts:        HashMap<String, usize>,
}

impl InfraMetrics {
    pub fn new() -> Self {
        InfraMetrics {
            total_requests:   0,
            success_requests: 0,
            error_requests:   0,
            mutation_count:   0,
            migration_count:  0,
            event_count:      0,
            auth_success:     0,
            auth_failure:     0,
            rate_limited:     0,
            last_activity:    unix_now(),
            db_counts:        HashMap::new(),
        }
    }

    pub fn record_request(&mut self, status: u16) {
        self.total_requests += 1;
        self.last_activity   = unix_now();
        if status < 400 { self.success_requests += 1; }
        else            { self.error_requests   += 1; }
        if status == 429 { self.rate_limited += 1; }
        if status == 401 || status == 403 { self.auth_failure += 1; }
    }

    pub fn success_rate(&self) -> f64 {
        if self.total_requests == 0 { return 100.0; }
        (self.success_requests as f64 / self.total_requests as f64) * 100.0
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "requests": {
                "total":    self.total_requests,
                "success":  self.success_requests,
                "error":    self.error_requests,
                "rate_limited": self.rate_limited,
                "success_rate_pct": format!("{:.1}", self.success_rate()),
            },
            "operations": {
                "mutations":  self.mutation_count,
                "migrations": self.migration_count,
                "events":     self.event_count,
            },
            "auth": {
                "success": self.auth_success,
                "failure": self.auth_failure,
            },
            "db_counts":      self.db_counts,
            "last_activity":  self.last_activity,
        })
    }
}

impl Default for InfraMetrics {
    fn default() -> Self { Self::new() }
}

// ─── Timeline ────────────────────────────────────────────

pub struct Timeline {
    records: Vec<EvidenceRecord>,
    capacity: usize,
}

impl Timeline {
    pub fn new(capacity: usize) -> Self {
        Timeline { records: Vec::new(), capacity }
    }

    pub fn push(&mut self, record: EvidenceRecord) {
        self.records.push(record);
        if self.records.len() > self.capacity {
            self.records.remove(0);
        }
    }

    pub fn all(&self) -> &[EvidenceRecord] {
        &self.records
    }

    pub fn recent(&self, n: usize) -> Vec<&EvidenceRecord> {
        self.records.iter().rev().take(n).collect()
    }

    pub fn by_kind(&self, kind: &EvidenceKind) -> Vec<&EvidenceRecord> {
        self.records.iter().filter(|r| &r.kind == kind).collect()
    }

    pub fn success_count(&self) -> usize {
        self.records.iter().filter(|r| r.success).count()
    }

    pub fn failure_count(&self) -> usize {
        self.records.iter().filter(|r| !r.success).count()
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "total":    self.records.len(),
            "success":  self.success_count(),
            "failure":  self.failure_count(),
            "records":  self.records.iter().map(|r| r.to_json()).collect::<Vec<_>>(),
        })
    }
}

// ─── EvidenceCollector (공유 가능) ───────────────────────

pub struct EvidenceCollector {
    pub timeline: Mutex<Timeline>,
    pub metrics:  Mutex<InfraMetrics>,
}

impl EvidenceCollector {
    pub fn new(capacity: usize) -> Self {
        EvidenceCollector {
            timeline: Mutex::new(Timeline::new(capacity)),
            metrics:  Mutex::new(InfraMetrics::new()),
        }
    }

    pub fn record(&self, r: EvidenceRecord) {
        self.timeline.lock().unwrap().push(r);
    }

    pub fn record_request(&self, status: u16) {
        self.metrics.lock().unwrap().record_request(status);
    }

    pub fn inc_mutation(&self) {
        self.metrics.lock().unwrap().mutation_count += 1;
    }

    pub fn inc_migration(&self) {
        self.metrics.lock().unwrap().migration_count += 1;
    }

    pub fn inc_event(&self) {
        self.metrics.lock().unwrap().event_count += 1;
    }

    pub fn summary_json(&self) -> serde_json::Value {
        let tl = self.timeline.lock().unwrap();
        let m  = self.metrics.lock().unwrap();
        serde_json::json!({
            "timeline": tl.to_json(),
            "metrics":  m.to_json(),
        })
    }
}

// ─── HTML 관제 센터 렌더러 ───────────────────────────────

pub fn render_control_center(
    collector: &EvidenceCollector,
    version: &str,
    uptime_secs: u64,
) -> String {
    let tl      = collector.timeline.lock().unwrap();
    let metrics = collector.metrics.lock().unwrap();

    let success_rate = format!("{:.1}", metrics.success_rate());

    // 타임라인 HTML
    let timeline_items = tl.recent(50).iter().map(|r| {
        let meta = if r.metrics != serde_json::Value::Null && r.metrics != serde_json::json!({}) {
            format!("<pre class='meta'>{}</pre>",
                serde_json::to_string_pretty(&r.metrics).unwrap_or_default())
        } else { String::new() };

        format!(
            r#"<div class="tl-item {ok}">
  <div class="tl-dot" style="background:{color}"></div>
  <div class="tl-body">
    <div class="tl-header">
      <span class="tl-icon">{icon}</span>
      <span class="tl-title">{title}</span>
      <span class="tl-badge" style="background:{color}22;color:{color}">{kind}</span>
      <span class="tl-time">{time}</span>
    </div>
    <div class="tl-desc">{desc}</div>
    {meta}
  </div>
</div>"#,
            ok    = if r.success { "ok" } else { "fail" },
            color = r.kind.color(),
            icon  = r.kind.icon(),
            title = r.title,
            kind  = r.kind.as_str(),
            time  = r.relative_time(),
            desc  = r.description,
            meta  = meta,
        )
    }).collect::<Vec<_>>().join("\n");

    let timeline_empty = if tl.all().is_empty() {
        r#"<div class="empty">아직 기록된 이벤트가 없습니다.</div>"#
    } else { "" };

    // DB 테이블 현황
    let db_rows = if metrics.db_counts.is_empty() {
        "<tr><td colspan='2' style='color:var(--muted)'>테이블 없음</td></tr>".to_string()
    } else {
        metrics.db_counts.iter().map(|(t, c)| {
            format!("<tr><td>{}</td><td class='num-cell'>{}</td></tr>", t, c)
        }).collect::<Vec<_>>().join("\n")
    };

    format!(r#"<!DOCTYPE html>
<html lang="ko">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>World Engine — 관제 센터</title>
<style>
:root{{
  --bg:#0a0c14;--surface:#111420;--surface2:#1a1d2e;--border:#1e2235;
  --text:#e2e8f0;--muted:#4a5568;--accent:#6366f1;
  --green:#22c55e;--red:#ef4444;--yellow:#f59e0b;
}}
*{{box-sizing:border-box;margin:0;padding:0}}
body{{background:var(--bg);color:var(--text);font-family:'Segoe UI',sans-serif;padding:1.5rem}}
/* 헤더 */
.header{{display:flex;align-items:center;gap:1rem;margin-bottom:1.5rem}}
.header h1{{font-size:1.5rem;color:var(--accent)}}
.header .ver{{color:var(--muted);font-size:.8rem}}
.header .uptime{{margin-left:auto;color:var(--muted);font-size:.8rem}}
/* KPI 카드 */
.kpi-grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:.75rem;margin-bottom:1.5rem}}
.kpi{{background:var(--surface);border:1px solid var(--border);border-radius:.75rem;padding:1rem;text-align:center}}
.kpi .val{{font-size:1.8rem;font-weight:700}}
.kpi .lbl{{font-size:.7rem;color:var(--muted);margin-top:.2rem;text-transform:uppercase}}
.kpi.green .val{{color:var(--green)}}
.kpi.red   .val{{color:var(--red)}}
.kpi.blue  .val{{color:var(--accent)}}
.kpi.yellow .val{{color:var(--yellow)}}
/* 2열 레이아웃 */
.cols{{display:grid;grid-template-columns:1fr 320px;gap:1rem;margin-bottom:1rem}}
@media(max-width:900px){{.cols{{grid-template-columns:1fr}}}}
/* 타임라인 */
.panel{{background:var(--surface);border:1px solid var(--border);border-radius:.75rem;padding:1.25rem}}
.panel h2{{font-size:.9rem;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin-bottom:1rem}}
.tl-item{{display:flex;gap:.75rem;margin-bottom:1rem;padding-bottom:1rem;border-bottom:1px solid var(--border)}}
.tl-item:last-child{{border-bottom:none;margin-bottom:0}}
.tl-dot{{width:10px;height:10px;border-radius:50%;flex-shrink:0;margin-top:.35rem}}
.tl-body{{flex:1;min-width:0}}
.tl-header{{display:flex;align-items:center;gap:.4rem;flex-wrap:wrap;margin-bottom:.25rem}}
.tl-icon{{font-size:1rem}}
.tl-title{{font-weight:600;font-size:.9rem}}
.tl-badge{{font-size:.65rem;padding:.1rem .45rem;border-radius:999px;font-weight:600}}
.tl-time{{color:var(--muted);font-size:.75rem;margin-left:auto}}
.tl-desc{{color:var(--muted);font-size:.8rem}}
.tl-item.fail .tl-title{{color:var(--red)}}
pre.meta{{background:var(--surface2);border:1px solid var(--border);border-radius:.4rem;
          padding:.5rem;font-size:.7rem;color:#93c5fd;margin-top:.4rem;overflow-x:auto}}
.empty{{color:var(--muted);font-size:.85rem;text-align:center;padding:2rem}}
/* DB 테이블 */
.db-table{{width:100%;border-collapse:collapse;font-size:.85rem}}
.db-table tr{{border-bottom:1px solid var(--border)}}
.db-table td{{padding:.5rem .25rem}}
.db-table .num-cell{{text-align:right;color:var(--accent);font-weight:600}}
/* 성공률 바 */
.bar-wrap{{background:var(--border);border-radius:999px;height:8px;margin-top:.5rem}}
.bar-fill{{background:var(--green);border-radius:999px;height:8px;transition:width .3s}}
/* 푸터 */
footer{{margin-top:1.5rem;text-align:center;color:var(--muted);font-size:.75rem}}
footer a{{color:var(--accent)}}
.refresh{{background:var(--accent);color:#fff;border:none;padding:.35rem .8rem;
          border-radius:.4rem;cursor:pointer;font-size:.75rem}}
</style>
</head>
<body>
<div class="header">
  <span style="font-size:1.5rem">⚡</span>
  <h1>World Engine 관제 센터</h1>
  <span class="ver">v{version}</span>
  <div class="uptime">⏱ 가동 {uptime}s &nbsp;
    <button class="refresh" onclick="location.reload()">새로고침</button>
  </div>
</div>

<!-- KPI 카드 -->
<div class="kpi-grid">
  <div class="kpi green">
    <div class="val">{total_req}</div>
    <div class="lbl">총 요청</div>
  </div>
  <div class="kpi green">
    <div class="val">{success_rate}%</div>
    <div class="lbl">성공률</div>
  </div>
  <div class="kpi red">
    <div class="val">{errors}</div>
    <div class="lbl">에러</div>
  </div>
  <div class="kpi yellow">
    <div class="val">{rate_limited}</div>
    <div class="lbl">Rate Limited</div>
  </div>
  <div class="kpi blue">
    <div class="val">{mutations}</div>
    <div class="lbl">Mutations</div>
  </div>
  <div class="kpi blue">
    <div class="val">{migrations}</div>
    <div class="lbl">Migrations</div>
  </div>
  <div class="kpi blue">
    <div class="val">{events}</div>
    <div class="lbl">Events</div>
  </div>
  <div class="kpi">
    <div class="val" style="color:var(--yellow)">{tl_total}</div>
    <div class="lbl">기록</div>
  </div>
</div>

<!-- 성공률 바 -->
<div style="margin-bottom:1.5rem;background:var(--surface);border:1px solid var(--border);
            border-radius:.75rem;padding:1rem">
  <div style="display:flex;justify-content:space-between;font-size:.8rem;margin-bottom:.4rem">
    <span>요청 성공률</span>
    <span style="color:var(--green)">{success_rate}%</span>
  </div>
  <div class="bar-wrap">
    <div class="bar-fill" style="width:{success_rate}%"></div>
  </div>
</div>

<div class="cols">
  <!-- 타임라인 -->
  <div class="panel">
    <h2>📜 기술 진화 타임라인 (최근 50개)</h2>
    {timeline_empty}
    {timeline_items}
  </div>

  <!-- DB 현황 + 통계 -->
  <div>
    <div class="panel" style="margin-bottom:1rem">
      <h2>🗄 DB 유입 현황</h2>
      <table class="db-table">
        <tr style="color:var(--muted);font-size:.7rem">
          <td>테이블</td><td style="text-align:right">레코드</td>
        </tr>
        {db_rows}
      </table>
    </div>

    <div class="panel">
      <h2>📊 인증 통계</h2>
      <table class="db-table">
        <tr><td>인증 성공</td><td class="num-cell" style="color:var(--green)">{auth_ok}</td></tr>
        <tr><td>인증 실패</td><td class="num-cell" style="color:var(--red)">{auth_fail}</td></tr>
        <tr><td>Rate Limited</td><td class="num-cell" style="color:var(--yellow)">{rate_limited}</td></tr>
      </table>
    </div>
  </div>
</div>

<footer>
  World Engine 관제 센터 ·
  <a href="/dashboard">대시보드</a> ·
  <a href="/evidence">JSON 타임라인</a> ·
  <a href="/metrics">메트릭</a> ·
  <a href="/health">헬스</a>
</footer>

<script>setTimeout(()=>location.reload(), 15000);</script>
</body>
</html>"#,
        version        = version,
        uptime         = uptime_secs,
        total_req      = metrics.total_requests,
        success_rate   = success_rate,
        errors         = metrics.error_requests,
        rate_limited   = metrics.rate_limited,
        mutations      = metrics.mutation_count,
        migrations     = metrics.migration_count,
        events         = metrics.event_count,
        tl_total       = tl.all().len(),
        auth_ok        = metrics.auth_success,
        auth_fail      = metrics.auth_failure,
        db_rows        = db_rows,
        timeline_empty = timeline_empty,
        timeline_items = timeline_items,
    )
}

// ─── 내부 유틸 ───────────────────────────────────────────

static EVIDENCE_ID: std::sync::atomic::AtomicU64
    = std::sync::atomic::AtomicU64::new(1);

fn next_id() -> u64 {
    EVIDENCE_ID.fetch_add(1, std::sync::atomic::Ordering::SeqCst)
}

fn unix_now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

toolUseResult.content:
// ============================================================
// Evidence Visualization — 관제 센터 & 타임라인 아카이빙
// ============================================================
// "기록이 증명" — 시스템의 모든 변화를 자동으로 기록하고
// 한눈에 볼 수 있는 HTML 관제 센터를 생성
// ============================================================

use std::collections::HashMap;
use std::sync::Mutex;
use std::time::{SystemTime, UNIX_EPOCH};

// ─── EvidenceKind ────────────────────────────────────────

#[derive(Debug, Clone, PartialEq)]
pub enum EvidenceKind {
    Build,
    TestRun,
    Deployment,
    SchemaMutation,
    Migration,
    EventPublished,
    AuthEvent,
    Custom(String),
}

impl EvidenceKind {
    pub fn as_str(&self) -> &str {
        match self {
            EvidenceKind::Build          => "build",
            EvidenceKind::TestRun        => "test_run",
            EvidenceKind::Deployment     => "deployment",
            EvidenceKind::SchemaMutation => "schema_mutation",
            EvidenceKind::Migration      => "migration",
            EvidenceKind::EventPublished => "event_published",
            EvidenceKind::AuthEvent      => "auth_event",
            EvidenceKind::Custom(s)      => s.as_str(),
        }
    }

    pub fn from_str(s: &str) -> Self {
        match s {
            "build"           => EvidenceKind::Build,
            "test_run"        => EvidenceKind::TestRun,
            "deployment"      => EvidenceKind::Deployment,
            "schema_mutation" => EvidenceKind::SchemaMutation,
            "migration"       => EvidenceKind::Migration,
            "event_published" => EvidenceKind::EventPublished,
            "auth_event"      => EvidenceKind::AuthEvent,
            other             => EvidenceKind::Custom(other.to_string()),
        }
    }

    /// 시각화용 색상 (CSS)
    pub fn color(&self) -> &'static str {
        match self {
            EvidenceKind::Build          => "#22c55e",
            EvidenceKind::TestRun        => "#6366f1",
            EvidenceKind::Deployment     => "#f59e0b",
            EvidenceKind::SchemaMutation => "#ec4899",
            EvidenceKind::Migration      => "#14b8a6",
            EvidenceKind::EventPublished => "#8b5cf6",
            EvidenceKind::AuthEvent      => "#64748b",
            EvidenceKind::Custom(_)      => "#94a3b8",
        }
    }

    pub fn icon(&self) -> &'static str {
        match self {
            EvidenceKind::Build          => "🔨",
            EvidenceKind::TestRun        => "✅",
            EvidenceKind::Deployment     => "🚀",
            EvidenceKind::SchemaMutation => "🔧",
            EvidenceKind::Migration      => "📦",
            EvidenceKind::EventPublished => "📡",
            EvidenceKind::AuthEvent      => "🔑",
            EvidenceKind::Custom(_)      => "📌",
        }
    }
}

// ─── EvidenceRecord ──────────────────────────────────────

#[derive(Debug, Clone)]
pub struct EvidenceRecord {
    pub id:          u64,
    pub kind:        EvidenceKind,
    pub title:       String,
    pub description: String,
    pub metrics:     serde_json::Value,
    pub tags:        Vec<String>,
    pub timestamp:   u64,
    pub success:     bool,
}

impl EvidenceRecord {
    pub fn new(
        kind: EvidenceKind,
        title: &str,
        description: &str,
        metrics: serde_json::Value,
        success: bool,
    ) -> Self {
        EvidenceRecord {
            id:          next_id(),
            kind,
            title:       title.to_string(),
            description: description.to_string(),
            metrics,
            tags:        Vec::new(),
            timestamp:   unix_now(),
            success,
        }
    }

    pub fn with_tag(mut self, tag: &str) -> Self {
        self.tags.push(tag.to_string());
        self
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "id":          self.id,
            "kind":        self.kind.as_str(),
            "title":       self.title,
            "description": self.description,
            "metrics":     self.metrics,
            "tags":        self.tags,
            "timestamp":   self.timestamp,
            "success":     self.success,
            "color":       self.kind.color(),
            "icon":        self.kind.icon(),
        })
    }

    /// 상대 시각 표시 ("3분 전", "2시간 전")
    pub fn relative_time(&self) -> String {
        let now  = unix_now();
        let diff = now.saturating_sub(self.timestamp);
        if diff < 60         { format!("{}초 전", diff) }
        else if diff < 3600  { format!("{}분 전", diff / 60) }
        else if diff < 86400 { format!("{}시간 전", diff / 3600) }
        else                  { format!("{}일 전", diff / 86400) }
    }
}

// ─── InfraMetrics (실시간 인프라 지표) ──────────────────

#[derive(Debug)]
pub struct InfraMetrics {
    pub total_requests:   u64,
    pub success_requests: u64,
    pub error_requests:   u64,
    pub mutation_count:   u64,
    pub migration_count:  u64,
    pub event_count:      u64,
    pub auth_success:     u64,
    pub auth_failure:     u64,
    pub rate_limited:     u64,
    pub last_activity:    u64,
    /// 테이블별 DB 레코드 수 (외부에서 주입)
    pub db_counts:        HashMap<String, usize>,
}

impl InfraMetrics {
    pub fn new() -> Self {
        InfraMetrics {
            total_requests:   0,
            success_requests: 0,
            error_requests:   0,
            mutation_count:   0,
            migration_count:  0,
            event_count:      0,
            auth_success:     0,
            auth_failure:     0,
            rate_limited:     0,
            last_activity:    unix_now(),
            db_counts:        HashMap::new(),
        }
    }

    pub fn record_request(&mut self, status: u16) {
        self.total_requests += 1;
        self.last_activity   = unix_now();
        if status < 400 { self.success_requests += 1; }
        else            { self.error_requests   += 1; }
        if status == 429 { self.rate_limited += 1; }
        if status == 401 || status == 403 { self.auth_failure += 1; }
    }

    pub fn success_rate(&self) -> f64 {
        if self.total_requests == 0 { return 100.0; }
        (self.success_requests as f64 / self.total_requests as f64) * 100.0
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "requests": {
                "total":    self.total_requests,
                "success":  self.success_requests,
                "error":    self.error_requests,
                "rate_limited": self.rate_limited,
                "success_rate_pct": format!("{:.1}", self.success_rate()),
            },
            "operations": {
                "mutations":  self.mutation_count,
                "migrations": self.migration_count,
                "events":     self.event_count,
            },
            "auth": {
                "success": self.auth_success,
                "failure": self.auth_failure,
            },
            "db_counts":      self.db_counts,
            "last_activity":  self.last_activity,
        })
    }
}

impl Default for InfraMetrics {
    fn default() -> Self { Self::new() }
}

// ─── Timeline ────────────────────────────────────────────

pub struct Timeline {
    records: Vec<EvidenceRecord>,
    capacity: usize,
}

impl Timeline {
    pub fn new(capacity: usize) -> Self {
        Timeline { records: Vec::new(), capacity }
    }

    pub fn push(&mut self, record: EvidenceRecord) {
        self.records.push(record);
        if self.records.len() > self.capacity {
            self.records.remove(0);
        }
    }

    pub fn all(&self) -> &[EvidenceRecord] {
        &self.records
    }

    pub fn recent(&self, n: usize) -> Vec<&EvidenceRecord> {
        self.records.iter().rev().take(n).collect()
    }

    pub fn by_kind(&self, kind: &EvidenceKind) -> Vec<&EvidenceRecord> {
        self.records.iter().filter(|r| &r.kind == kind).collect()
    }

    pub fn success_count(&self) -> usize {
        self.records.iter().filter(|r| r.success).count()
    }

    pub fn failure_count(&self) -> usize {
        self.records.iter().filter(|r| !r.success).count()
    }

    pub fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "total":    self.records.len(),
            "success":  self.success_count(),
            "failure":  self.failure_count(),
            "records":  self.records.iter().map(|r| r.to_json()).collect::<Vec<_>>(),
        })
    }
}

// ─── EvidenceCollector (공유 가능) ───────────────────────

pub struct EvidenceCollector {
    pub timeline: Mutex<Timeline>,
    pub metrics:  Mutex<InfraMetrics>,
}

impl EvidenceCollector {
    pub fn new(capacity: usize) -> Self {
        EvidenceCollector {
            timeline: Mutex::new(Timeline::new(capacity)),
            metrics:  Mutex::new(InfraMetrics::new()),
        }
    }

    pub fn record(&self, r: EvidenceRecord) {
        self.timeline.lock().unwrap().push(r);
    }

    pub fn record_request(&self, status: u16) {
        self.metrics.lock().unwrap().record_request(status);
    }

    pub fn inc_mutation(&self) {
        self.metrics.lock().unwrap().mutation_count += 1;
    }

    pub fn inc_migration(&self) {
        self.metrics.lock().unwrap().migration_count += 1;
    }

    pub fn inc_event(&self) {
        self.metrics.lock().unwrap().event_count += 1;
    }

    pub fn summary_json(&self) -> serde_json::Value {
        let tl = self.timeline.lock().unwrap();
        let m  = self.metrics.lock().unwrap();
        serde_json::json!({
            "timeline": tl.to_json(),
            "metrics":  m.to_json(),
        })
    }
}

// ─── HTML 관제 센터 렌더러 ───────────────────────────────

