    81→// ─── EvidenceRecord ──────────────────────────────────────
    82→
    83→#[derive(Debug, Clone)]
    84→pub struct EvidenceRecord {
    85→    pub id:          u64,
    86→    pub kind:        EvidenceKind,
    87→    pub title:       String,
    88→    pub description: String,
    89→    pub metrics:     serde_json::Value,
    90→    pub tags:        Vec<String>,
    91→    pub timestamp:   u64,
    92→    pub success:     bool,
    93→}
    94→
    95→impl EvidenceRecord {
    96→    pub fn new(
    97→        kind: EvidenceKind,
    98→        title: &str,
    99→        description: &str,
   100→        metrics: serde_json::Value,
   101→        success: bool,
   102→    ) -> Self {
   103→        EvidenceRecord {
   104→            id:          next_id(),
   105→            kind,
   106→            title:       title.to_string(),
   107→            description: description.to_string(),
   108→            metrics,
   109→            tags:        Vec::new(),
   110→            timestamp:   unix_now(),
   111→            success,
   112→        }
   113→    }
   114→
   115→    pub fn with_tag(mut self, tag: &str) -> Self {
   116→        self.tags.push(tag.to_string());
   117→        self
   118→    }
   119→
   120→    pub fn to_json(&self) -> serde_json::Value {
   121→        serde_json::json!({
   122→            "id":          self.id,
   123→            "kind":        self.kind.as_str(),
   124→            "title":       self.title,
   125→            "description": self.description,
   126→            "metrics":     self.metrics,
   127→            "tags":        self.tags,
   128→            "timestamp":   self.timestamp,
   129→            "success":     self.success,
   130→            "color":       self.kind.color(),
   131→            "icon":        self.kind.icon(),
   132→        })
   133→    }
   134→
   135→    /// 상대 시각 표시 ("3분 전", "2시간 전")
   136→    pub fn relative_time(&self) -> String {
   137→        let now  = unix_now();
   138→        let diff = now.saturating_sub(self.timestamp);
   139→        if diff < 60         { format!("{}초 전", diff) }
   140→        else if diff < 3600  { format!("{}분 전", diff / 60) }
   141→        else if diff < 86400 { format!("{}시간 전", diff / 3600) }
   142→        else                  { format!("{}일 전", diff / 86400) }
   143→    }
   144→}
   145→
   146→// ─── InfraMetrics (실시간 인프라 지표) ──────────────────
   147→
   148→#[derive(Debug)]
   149→pub struct InfraMetrics {
   150→    pub total_requests:   u64,
   151→    pub success_requests: u64,
   152→    pub error_requests:   u64,
   153→    pub mutation_count:   u64,
   154→    pub migration_count:  u64,
   155→    pub event_count:      u64,
   156→    pub auth_success:     u64,
   157→    pub auth_failure:     u64,
   158→    pub rate_limited:     u64,
   159→    pub last_activity:    u64,
   160→    /// 테이블별 DB 레코드 수 (외부에서 주입)
   161→    pub db_counts:        HashMap<String, usize>,
   162→}
   163→
   164→impl InfraMetrics {
   165→    pub fn new() -> Self {
   166→        InfraMetrics {
   167→            total_requests:   0,
   168→            success_requests: 0,
   169→            error_requests:   0,
   170→            mutation_count:   0,
   171→            migration_count:  0,
   172→            event_count:      0,
   173→            auth_success:     0,
   174→            auth_failure:     0,
   175→            rate_limited:     0,
   176→            last_activity:    unix_now(),
   177→            db_counts:        HashMap::new(),
   178→        }
   179→    }
   180→
   181→    pub fn record_request(&mut self, status: u16) {
   182→        self.total_requests += 1;
   183→        self.last_activity   = unix_now();
   184→        if status < 400 { self.success_requests += 1; }
   185→        else            { self.error_requests   += 1; }
   186→        if status == 429 { self.rate_limited += 1; }
   187→        if status == 401 || status == 403 { self.auth_failure += 1; }
   188→    }
   189→
   190→    pub fn success_rate(&self) -> f64 {
   191→        if self.total_requests == 0 { return 100.0; }
   192→        (self.success_requests as f64 / self.total_requests as f64) * 100.0
   193→    }
   194→
   195→    pub fn to_json(&self) -> serde_json::Value {
   196→        serde_json::json!({
   197→            "requests": {
   198→                "total":    self.total_requests,
   199→                "success":  self.success_requests,
   200→                "error":    self.error_requests,
   201→                "rate_limited": self.rate_limited,
   202→                "success_rate_pct": format!("{:.1}", self.success_rate()),
   203→            },
   204→            "operations": {
   205→                "mutations":  self.mutation_count,
   206→                "migrations": self.migration_count,
   207→                "events":     self.event_count,
   208→            },
   209→            "auth": {
   210→                "success": self.auth_success,
   211→                "failure": self.auth_failure,
   212→            },
   213→            "db_counts":      self.db_counts,
   214→            "last_activity":  self.last_activity,
   215→        })
   216→    }
   217→}
   218→
   219→impl Default for InfraMetrics {
   220→    fn default() -> Self { Self::new() }
   221→}
   222→
   223→// ─── Timeline ────────────────────────────────────────────
   224→
   225→pub struct Timeline {
   226→    records: Vec<EvidenceRecord>,
   227→    capacity: usize,
   228→}
   229→
   230→impl Timeline {
   231→    pub fn new(capacity: usize) -> Self {
   232→        Timeline { records: Vec::new(), capacity }
   233→    }
   234→
   235→    pub fn push(&mut self, record: EvidenceRecord) {
   236→        self.records.push(record);
   237→        if self.records.len() > self.capacity {
   238→            self.records.remove(0);
   239→        }
   240→    }
   241→
   242→    pub fn all(&self) -> &[EvidenceRecord] {
   243→        &self.records
   244→    }
   245→
   246→    pub fn recent(&self, n: usize) -> Vec<&EvidenceRecord> {
   247→        self.records.iter().rev().take(n).collect()
   248→    }
   249→
   250→    pub fn by_kind(&self, kind: &EvidenceKind) -> Vec<&EvidenceRecord> {
   251→        self.records.iter().filter(|r| &r.kind == kind).collect()
   252→    }
   253→
   254→    pub fn success_count(&self) -> usize {
   255→        self.records.iter().filter(|r| r.success).count()
   256→    }
   257→
   258→    pub fn failure_count(&self) -> usize {
   259→        self.records.iter().filter(|r| !r.success).count()
   260→    }
   261→
   262→    pub fn to_json(&self) -> serde_json::Value {
   263→        serde_json::json!({
   264→            "total":    self.records.len(),
   265→            "success":  self.success_count(),
   266→            "failure":  self.failure_count(),
   267→            "records":  self.records.iter().map(|r| r.to_json()).collect::<Vec<_>>(),
   268→        })
   269→    }
   270→}
   271→
   272→// ─── EvidenceCollector (공유 가능) ───────────────────────
   273→
   274→pub struct EvidenceCollector {
   275→    pub timeline: Mutex<Timeline>,
   276→    pub metrics:  Mutex<InfraMetrics>,
   277→}
   278→
   279→impl EvidenceCollector {
   280→    pub fn new(capacity: usize) -> Self {
   281→        EvidenceCollector {
   282→            timeline: Mutex::new(Timeline::new(capacity)),
   283→            metrics:  Mutex::new(InfraMetrics::new()),
   284→        }
   285→    }
   286→
   287→    pub fn record(&self, r: EvidenceRecord) {
   288→        self.timeline.lock().unwrap().push(r);
   289→    }
   290→
   291→    pub fn record_request(&self, status: u16) {
   292→        self.metrics.lock().unwrap().record_request(status);
   293→    }
   294→
   295→    pub fn inc_mutation(&self) {
   296→        self.metrics.lock().unwrap().mutation_count += 1;
   297→    }
   298→
   299→    pub fn inc_migration(&self) {
   300→        self.metrics.lock().unwrap().migration_count += 1;
   301→    }
   302→
   303→    pub fn inc_event(&self) {
   304→        self.metrics.lock().unwrap().event_count += 1;
   305→    }
   306→
   307→    pub fn summary_json(&self) -> serde_json::Value {
   308→        let tl = self.timeline.lock().unwrap();
   309→        let m  = self.metrics.lock().unwrap();
   310→        serde_json::json!({
   311→            "timeline": tl.to_json(),
   312→            "metrics":  m.to_json(),
   313→        })
   314→    }
   315→}
   316→
   317→// ─── HTML 관제 센터 렌더러 ───────────────────────────────
   318→
   319→pub fn render_control_center(
   320→    collector: &EvidenceCollector,
   321→    version: &str,
   322→    uptime_secs: u64,
   323→) -> String {
   324→    let tl      = collector.timeline.lock().unwrap();
   325→    let metrics = collector.metrics.lock().unwrap();
   326→
   327→    let success_rate = format!("{:.1}", metrics.success_rate());
   328→
   329→    // 타임라인 HTML
   330→    let timeline_items = tl.recent(50).iter().map(|r| {
   331→        let meta = if r.metrics != serde_json::Value::Null && r.metrics != serde_json::json!({}) {
   332→            format!("<pre class='meta'>{}</pre>",
   333→                serde_json::to_string_pretty(&r.metrics).unwrap_or_default())
   334→        } else { String::new() };
   335→
   336→        format!(
   337→            r#"<div class="tl-item {ok}">
   338→  <div class="tl-dot" style="background:{color}"></div>
   339→  <div class="tl-body">
   340→    <div class="tl-header">
   341→      <span class="tl-icon">{icon}</span>
   342→      <span class="tl-title">{title}</span>
   343→      <span class="tl-badge" style="background:{color}22;color:{color}">{kind}</span>
   344→      <span class="tl-time">{time}</span>
   345→    </div>
   346→    <div class="tl-desc">{desc}</div>
   347→    {meta}
   348→  </div>
   349→</div>"#,
   350→            ok    = if r.success { "ok" } else { "fail" },
   351→            color = r.kind.color(),
   352→            icon  = r.kind.icon(),
   353→            title = r.title,
   354→            kind  = r.kind.as_str(),
   355→            time  = r.relative_time(),
   356→            desc  = r.description,
   357→            meta  = meta,
   358→        )
   359→    }).collect::<Vec<_>>().join("\n");
   360→
   361→    let timeline_empty = if tl.all().is_empty() {
   362→        r#"<div class="empty">아직 기록된 이벤트가 없습니다.</div>"#
   363→    } else { "" };
   364→
   365→    // DB 테이블 현황
   366→    let db_rows = if metrics.db_counts.is_empty() {
   367→        "<tr><td colspan='2' style='color:var(--muted)'>테이블 없음</td></tr>".to_string()
   368→    } else {
   369→        metrics.db_counts.iter().map(|(t, c)| {
   370→            format!("<tr><td>{}</td><td class='num-cell'>{}</td></tr>", t, c)
   371→        }).collect::<Vec<_>>().join("\n")
   372→    };
   373→
   374→    format!(r#"<!DOCTYPE html>
   375→<html lang="ko">
