.db-table tr{{border-bottom:1px solid var(--border)}}
.db-table td{{padding:.5rem .25rem}}
.db-table .num-cell{{text-align:right;color:var(--accent);font-weight:600}}
/* 성공률 바 */
.bar-wrap{{background:var(--border);border-radius:999px;height:8px;margin-top:.5rem}}
.bar-fill{{background:var(--green);border-radius:999px;height:8px;transition:width .3s}}
/* 푸터 */
footer{{margin-top:1.5rem;text-align:center;color:var(--muted);font-size:.75rem}}
footer a{{color:var(--accent)}}
.refresh{{background:var(--accent);color:#fff;border:none;padding:.35rem .8rem;
          border-radius:.4rem;cursor:pointer;font-size:.75rem}}
</style>
</head>
<body>
<div class="header">
  <span style="font-size:1.5rem">⚡</span>
  <h1>World Engine 관제 센터</h1>
  <span class="ver">v{version}</span>
  <div class="uptime">⏱ 가동 {uptime}s &nbsp;
    <button class="refresh" onclick="location.reload()">새로고침</button>
  </div>
</div>

<!-- KPI 카드 -->
<div class="kpi-grid">
  <div class="kpi green">
    <div class="val">{total_req}</div>
    <div class="lbl">총 요청</div>
  </div>
  <div class="kpi green">
    <div class="val">{success_rate}%</div>
    <div class="lbl">성공률</div>
  </div>
  <div class="kpi red">
    <div class="val">{errors}</div>
    <div class="lbl">에러</div>
  </div>
  <div class="kpi yellow">
    <div class="val">{rate_limited}</div>
    <div class="lbl">Rate Limited</div>
  </div>
  <div class="kpi blue">
    <div class="val">{mutations}</div>
    <div class="lbl">Mutations</div>
  </div>
  <div class="kpi blue">
    <div class="val">{migrations}</div>
    <div class="lbl">Migrations</div>
  </div>
  <div class="kpi blue">
    <div class="val">{events}</div>
    <div class="lbl">Events</div>
  </div>
  <div class="kpi">
    <div class="val" style="color:var(--yellow)">{tl_total}</div>
    <div class="lbl">기록</div>
  </div>
</div>

<!-- 성공률 바 -->
<div style="margin-bottom:1.5rem;background:var(--surface);border:1px solid var(--border);
            border-radius:.75rem;padding:1rem">
  <div style="display:flex;justify-content:space-between;font-size:.8rem;margin-bottom:.4rem">
    <span>요청 성공률</span>
    <span style="color:var(--green)">{success_rate}%</span>
  </div>
  <div class="bar-wrap">
    <div class="bar-fill" style="width:{success_rate}%"></div>
  </div>
</div>

<div class="cols">
  <!-- 타임라인 -->
  <div class="panel">
    <h2>📜 기술 진화 타임라인 (최근 50개)</h2>
    {timeline_empty}
    {timeline_items}
  </div>

  <!-- DB 현황 + 통계 -->
  <div>
    <div class="panel" style="margin-bottom:1rem">
      <h2>🗄 DB 유입 현황</h2>
      <table class="db-table">
        <tr style="color:var(--muted);font-size:.7rem">
          <td>테이블</td><td style="text-align:right">레코드</td>
        </tr>
        {db_rows}
      </table>
    </div>

    <div class="panel">
      <h2>📊 인증 통계</h2>
      <table class="db-table">
        <tr><td>인증 성공</td><td class="num-cell" style="color:var(--green)">{auth_ok}</td></tr>
        <tr><td>인증 실패</td><td class="num-cell" style="color:var(--red)">{auth_fail}</td></tr>
        <tr><td>Rate Limited</td><td class="num-cell" style="color:var(--yellow)">{rate_limited}</td></tr>
      </table>
    </div>
  </div>
</div>

<footer>
  World Engine 관제 센터 ·
  <a href="/dashboard">대시보드</a> ·
  <a href="/evidence">JSON 타임라인</a> ·
  <a href="/metrics">메트릭</a> ·
  <a href="/health">헬스</a>
</footer>

<script>setTimeout(()=>location.reload(), 15000);</script>
</body>
</html>"#,
        version        = version,
        uptime         = uptime_secs,
        total_req      = metrics.total_requests,
        success_rate   = success_rate,
        errors         = metrics.error_requests,
        rate_limited   = metrics.rate_limited,
        mutations      = metrics.mutation_count,
        migrations     = metrics.migration_count,
        events         = metrics.event_count,
        tl_total       = tl.all().len(),
        auth_ok        = metrics.auth_success,
        auth_fail      = metrics.auth_failure,
        db_rows        = db_rows,
        timeline_empty = timeline_empty,
        timeline_items = timeline_items,
    )
}

// ─── 내부 유틸 ───────────────────────────────────────────

static EVIDENCE_ID: std::sync::atomic::AtomicU64
    = std::sync::atomic::AtomicU64::new(1);

fn next_id() -> u64 {
    EVIDENCE_ID.fetch_add(1, std::sync::atomic::Ordering::SeqCst)
}

fn unix_now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

