#[test]
fn test_router_evidence_record_endpoint() {
    use std::sync::Arc;
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = make_graph();
    let result = Synthesizer::synthesize(&graph);
    let ec = Arc::new(EvidenceCollector::new(100));
    let mut router = Router::from_graph(graph).with_evidence(Arc::clone(&ec));
    let body = r#"{"kind":"build","title":"Test Build","description":"Success","success":true}"#;
    let (status, json) = router.handle(&mut { result.db }, "POST", "/evidence/record", body);
    assert_eq!(status, 200);
    assert_eq!(json["ok"].as_bool().unwrap(), true);
    assert!(json["id"].as_u64().is_some());
    // 실제로 기록됐는지 확인
    let tl = ec.timeline.lock().unwrap();
    assert_eq!(tl.all().len(), 1);
    assert_eq!(tl.all()[0].title, "Test Build");
