#[test]
fn test_router_auto_records_requests() {
    use std::sync::Arc;
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = make_graph();
    let result = Synthesizer::synthesize(&graph);
    let ec = Arc::new(EvidenceCollector::new(100));
    let mut router = Router::from_graph(graph).with_evidence(Arc::clone(&ec));
    // 여러 요청 처리
    router.handle(&mut { result.db.clone() }, "GET", "/health", "");
    router.handle(&mut { result.db.clone() }, "GET", "/routes", "");
    router.handle(&mut { result.db.clone() }, "GET", "/nonexistent", ""); // 404
    // 요청 자동 기록 확인
    let j = ec.summary_json();
    assert_eq!(j["metrics"]["requests"]["total"].as_u64().unwrap(), 3);
    // 404는 error로 카운트
    assert!(j["metrics"]["requests"]["error"].as_u64().unwrap() >= 1);
}

#[test]
fn test_router_mutation_records_evidence() {
    use std::sync::Arc;
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = make_graph();
    let result = Synthesizer::synthesize(&graph);
    let ec = Arc::new(EvidenceCollector::new(100));
    let mut router = Router::from_graph(graph).with_evidence(Arc::clone(&ec));
    let body = r#"{"op":"add_field","intent":"EvidTest","schema":"Item","field_name":"price","field_type":"f64"}"#;
    let (status, _) = router.handle(&mut { result.db }, "POST", "/mutate", body);
    assert_eq!(status, 200);
    // mutation_count 증가 확인
    let j = ec.summary_json();
    assert_eq!(j["metrics"]["operations"]["mutations"].as_u64().unwrap(), 1);
    // 타임라인에도 기록됨
    let tl = ec.timeline.lock().unwrap();
    assert!(tl.all().iter().any(|r| r.kind == EvidenceKind::SchemaMutation));
}

#[test]
fn test_router_evidence_disabled_record_returns_400() {
    use world_engine::{binder::router::Router, synthesizer::Synthesizer};
    let graph = make_graph();
    let result = Synthesizer::synthesize(&graph);
    let mut router = Router::from_graph(graph);
    let (status, _) = router.handle(&mut { result.db }, "POST", "/evidence/record", "{}");
    assert_eq!(status, 400);
}

