};

// ─── EvidenceKind ─────────────────────────────────────────────

#[test]
fn test_kind_as_str_roundtrip() {
    let kinds = vec![
        EvidenceKind::Build,
        EvidenceKind::TestRun,
        EvidenceKind::Deployment,
        EvidenceKind::SchemaMutation,
        EvidenceKind::Migration,
        EvidenceKind::EventPublished,
        EvidenceKind::AuthEvent,
        EvidenceKind::Custom("my_event".into()),
    ];
    for k in &kinds {
        let s = k.as_str();
        let k2 = EvidenceKind::from_str(s);
        assert_eq!(k, &k2, "roundtrip failed for {:?}", k);
    }
}

#[test]
fn test_kind_color_not_empty() {
    let kinds = [
        EvidenceKind::Build, EvidenceKind::TestRun, EvidenceKind::Deployment,
        EvidenceKind::SchemaMutation, EvidenceKind::Migration,
        EvidenceKind::EventPublished, EvidenceKind::AuthEvent,
        EvidenceKind::Custom("x".into()),
    ];
    for k in &kinds {
        assert!(!k.color().is_empty(), "color empty for {:?}", k);
    }
}

#[test]
fn test_kind_icon_not_empty() {
    assert!(!EvidenceKind::Build.icon().is_empty());
    assert!(!EvidenceKind::TestRun.icon().is_empty());
    assert!(!EvidenceKind::Custom("x".into()).icon().is_empty());
}

