#[test]
fn test_record_new_fields() {
    let r = EvidenceRecord::new(
        EvidenceKind::Build,
        "Build OK",
        "Compiled in 3s",
        serde_json::json!({ "duration": 3 }),
        true,
    );
    assert_eq!(r.title, "Build OK");
    assert_eq!(r.kind,  EvidenceKind::Build);
    assert!(r.success);
    assert!(r.id > 0);
}

#[test]
fn test_record_with_tag() {
    let r = EvidenceRecord::new(EvidenceKind::TestRun, "T", "D", serde_json::Value::Null, true)
        .with_tag("ci")
        .with_tag("phase17");
    assert_eq!(r.tags.len(), 2);
    assert!(r.tags.contains(&"ci".to_string()));
}

#[test]
fn test_record_to_json_keys() {
    let r = EvidenceRecord::new(EvidenceKind::Deployment, "Deploy", "Desc", serde_json::Value::Null, false);
    let j = r.to_json();
    assert!(j["id"].as_u64().is_some());
    assert_eq!(j["kind"].as_str().unwrap(), "deployment");
    assert_eq!(j["title"].as_str().unwrap(), "Deploy");
    assert_eq!(j["success"].as_bool().unwrap(), false);
    assert!(j["color"].as_str().is_some());
    assert!(j["icon"].as_str().is_some());
}

#[test]
fn test_record_ids_unique() {
    let r1 = EvidenceRecord::new(EvidenceKind::Build, "A", "", serde_json::Value::Null, true);
    let r2 = EvidenceRecord::new(EvidenceKind::Build, "B", "", serde_json::Value::Null, true);
    assert_ne!(r1.id, r2.id);
}

